import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { getDiagnosticTimingProfileMapping } from "@gamify-surgery/balance-config";
import {
  SYNTHETIC_CLINICAL_RELEASE,
  QUESTION_CATALOG_RELEASE,
  QUESTION_BANK_BATCH2B_ROUND2_SOURCE_RELEASE,
} from "./synthetic-content";
import { QUESTION_SHIP_MANIFEST } from "./question-ship-manifest";
import { ANSWER_CHOICE_TIMING_REGISTRY } from "./answer-choice-timing";
import { answerChoiceTimingRegistryEntrySchema, syntheticClinicalReleaseSchema } from "./schema";
import packet from "../../../docs/research/question-topic-anorectal-benign-pelvic-floor-20261111.json";
import ledger from "../../../docs/research/sources-question-topic-anorectal-benign-pelvic-floor-20261111.json";

const slug = "anorectal-benign-pelvic-floor";
const sha = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const initialState = {
  release: sha(SYNTHETIC_CLINICAL_RELEASE),
  manifest: sha(QUESTION_SHIP_MANIFEST),
  timing: sha(ANSWER_CHOICE_TIMING_REGISTRY),
};
const topic = await import("./question-topic-anorectal-benign-pelvic-floor-20261111");

const beforeModules = await Promise.all([
  import("./development-batch/2026-09-10/anal-fissure"),
  import("./development-batch/2026-09-10/internal-hemorrhoids"),
  import("./development-batch/2026-09-12/complex-perianal-fistula"),
  import("./development-batch/2026-09-13/chronic-anal-fissure"),
  import("./development-batch/2026-09-17-bread-and-butter/perianal-abscess"),
  import("./development-batch/2026-09-17/fecal-incontinence"),
  import("./development-batch/2026-09-17/rectal-prolapse"),
  import("./development-batch/2026-09-29-statistics-ethics/ethics"),
  import("./development-batch/2026-10-10-variety-3/clinic"),
  import("./question-bank-batch2b-20261104"),
  import("./question-bank-batch2b-round2-20261104"),
  import("./question-new-n2-20261104"),
  import("./question-new-n2-round2-20261104"),
  import("./question-new-n2-round3-20261104"),
  import("./question-new-n3-20261105"),
  import("./question-new-n3-round2-20261105"),
  import("./question-new-n3-round3-20261105"),
]);

function collectObjects(value: unknown, output: object[] = [], seen = new WeakSet<object>()): object[] {
  if (!value || typeof value !== "object" || seen.has(value)) return output;
  seen.add(value);
  output.push(value);
  for (const item of Object.values(value)) collectObjects(item, output, seen);
  return output;
}
const originals = collectObjects([
  SYNTHETIC_CLINICAL_RELEASE,
  QUESTION_CATALOG_RELEASE,
  QUESTION_BANK_BATCH2B_ROUND2_SOURCE_RELEASE,
  ...beforeModules,
]);
const originalHashes = new Set(originals.map(sha));

const current = topic.ANORECTAL_TOPIC_CURRENT_ARTIFACTS;
const reviewed = packet.reviewRound.reviewedCatalog;
const review = JSON.parse(readFileSync(new URL("../../../docs/research/question-topic-anorectal-benign-pelvic-floor-review-20261111.json", import.meta.url), "utf8")) as Array<{ id: string; verdict: string }>;
const scoredNode = (node: object) => {
  const { terminalDispositions: _completion, ...scored } = node as Record<string, unknown>;
  return scored;
};

describe("anorectal independent-review response", () => {
  it("validates separate PASS and revision previews with no mixed or multi-node current case", () => {
    expect(syntheticClinicalReleaseSchema.safeParse(topic.ANORECTAL_TOPIC_SOURCE_RELEASE).success).toBe(true);
    expect(syntheticClinicalReleaseSchema.safeParse(topic.ANORECTAL_TOPIC_REVISION_SOURCE_RELEASE).success).toBe(true);
    expect(topic.ANORECTAL_TOPIC_CASES).toHaveLength(6);
    expect(topic.ANORECTAL_TOPIC_REVISION_ARTIFACTS.cases).toHaveLength(10);
    expect(current.questions).toHaveLength(16);
    expect(current.cases).toEqual(packet.normalizedRuntimeCases);
    expect(current.cases.every((clinicalCase) => clinicalCase.decisionNodes.length === 1)).toBe(true);
    expect(current.cases.every((clinicalCase) => clinicalCase.requiredClinicalSetting === "clinic")).toBe(true);
    expect(topic.ANORECTAL_TOPIC_MANIFEST.pipelinePassed).toBe(false);
    expect(topic.ANORECTAL_TOPIC_MANIFEST.managerAccepted).toBe(false);
    expect(topic.ANORECTAL_TOPIC_MANIFEST.clinicalApproval).toBe(false);
  });

  it("responds to all 22 exact independent decisions once without inventing a new PASS", () => {
    expect(packet.reviewRound.reviewedItems).toEqual(reviewed.proposals.map((proposal) =>
      packet.reviewRound.reviewedItems.find((entry) => entry.id === proposal.questionVariantId)!));
    expect(packet.reviewRound.dispositions.map((item) => item.reviewedQuestionVariantId).sort()).toEqual(review.map((item) => item.id).sort());
    expect(new Set(packet.reviewRound.dispositions.map((item) => item.reviewedQuestionVariantId)).size).toBe(22);
    expect(packet.reviewRound.dispositions.filter((item) => item.status === "pass-preserved")).toHaveLength(6);
    expect(packet.reviewRound.dispositions.filter((item) => item.status === "revised")).toHaveLength(10);
    expect(packet.reviewRound.dispositions.filter((item) => item.status === "parked")).toHaveLength(6);
    for (const item of packet.reviewRound.dispositions) {
      const decision = review.find((entry) => entry.id === item.reviewedQuestionVariantId)!;
      if (decision.verdict === "PASS") expect(item.status).toBe("pass-preserved");
      else {
        expect(["revised", "parked"]).toContain(item.status);
        expect(item.attemptCount).toBe(1);
      }
    }
    expect(createHash("sha256").update(readFileSync(new URL(`../../../${packet.reviewRound.reviewFile}`, import.meta.url))).digest("hex")).toBe(packet.reviewRound.reviewFileSha256);
  });

  it("retains every exact reviewed v1 question, node and whole case as history", () => {
    expect(reviewed.questions).toHaveLength(22);
    expect(reviewed.cases).toHaveLength(14);
    for (const proposal of reviewed.proposals) {
      expect(sha(reviewed.questions.find((question) => question.id === proposal.questionVariantId))).toBe(proposal.exactVersion.questionSha256);
      expect(sha(reviewed.nodes.find((node) => node.id === proposal.nodeId))).toBe(proposal.exactVersion.nodeSha256);
      expect(sha(reviewed.cases.find((clinicalCase) => clinicalCase.id === proposal.caseId))).toBe(proposal.exactVersion.caseSha256);
    }
  });

  it("preserves all six PASS questions and scored node fields exactly while isolating companions", () => {
    expect(packet.reviewRound.frozenPass).toHaveLength(6);
    for (const frozen of packet.reviewRound.frozenPass) {
      const originalNode = reviewed.nodes.find((node) => node.id === frozen.nodeId)!;
      const question = current.questions.find((item) => item.id === frozen.reviewedQuestionVariantId)!;
      const node = current.nodes.find((item) => item.id === frozen.nodeId)!;
      const originalCase = reviewed.cases.find((item) => item.id === frozen.caseId)!;
      const clinicalCase = current.cases.find((item) => item.decisionNodes.some((candidate) => candidate.id === frozen.nodeId))!;
      expect(sha(question)).toBe(frozen.questionSha256);
      expect(scoredNode(node)).toEqual(scoredNode(originalNode));
      for (const field of ["patientDisplayName", "prototypeDemographics", "presentation", "chiefComplaint", "approvedInstantiationProfiles", "patientPresentationVariantId"] as const) {
        expect(clinicalCase[field]).toEqual(originalCase[field]);
      }
      if (originalCase.decisionNodes.length === 1) expect(sha(clinicalCase)).toBe(frozen.caseSha256);
      else {
        expect(clinicalCase.id).not.toBe(originalCase.id);
        expect(clinicalCase.decisionNodes).toHaveLength(1);
        expect(packet.reviewRound.dispositions.find((item) => item.reviewedQuestionVariantId === frozen.reviewedQuestionVariantId)?.contextReviewStatus).toBe("pending_standalone_context_review");
      }
      if (originalNode.terminalDispositions.length > 0) expect(node.terminalDispositions).toEqual(originalNode.terminalDispositions);
      else expect(node.terminalDispositions.every((entry) => entry.kind === "no_terminal_outcome")).toBe(true);
    }
    expect(packet.reviewRound.dispositions.filter((item) => item.status === "pass-preserved" && item.splitFromCompanions)).toHaveLength(4);
  });

  it("keeps revised and parked items out of the primary PASS-only source view", () => {
    const passIds = new Set(review.filter((item) => item.verdict === "PASS").map((item) => item.id));
    expect(topic.ANORECTAL_TOPIC_QUESTIONS.every((question) => passIds.has(question.id))).toBe(true);
    expect(topic.ANORECTAL_TOPIC_REVISION_ARTIFACTS.questions.every((question) => question.id.endsWith(".v2") && !passIds.has(question.id))).toBe(true);
    for (const item of packet.parkedItems) {
      expect(item.attemptCount).toBe(1);
      expect(item.reviewStatus).toBe("needs_clinician_review");
      expect(item.attemptedRevision.reviewStatus).toBe("needs_clinician_review");
      expect(item.attemptedRevision.answerKey).toBeNull();
      expect(item.attemptedRevision.optionLabels).toHaveLength(3);
      expect(item.reason.length).toBeGreaterThan(130);
      expect(current.questions.some((question) => question.id === item.reviewedQuestionVariantId)).toBe(false);
      expect(item.attemptedRevision.executionStatus).toBe("non_executable_author_attempt");
    }
  });

  it("does not mutate or admit content to the default release, manifest or shared timing registry", () => {
    expect({ release: sha(SYNTHETIC_CLINICAL_RELEASE), manifest: sha(QUESTION_SHIP_MANIFEST), timing: sha(ANSWER_CHOICE_TIMING_REGISTRY) }).toEqual(initialState);
    for (const question of current.questions) {
      expect(QUESTION_SHIP_MANIFEST.accepted.some((entry) => entry.questionVariantId === question.id)).toBe(false);
      expect(SYNTHETIC_CLINICAL_RELEASE.cases.some((clinicalCase) => clinicalCase.decisionNodes.some((node) => node.questionVariantId === question.id))).toBe(false);
    }
  });

  it("retains all 77 original audit identities and their 272 finite profile occurrences", () => {
    const program = JSON.parse(readFileSync(new URL("../../../docs/research/question-topic-program-20261111.json", import.meta.url), "utf8")) as { inventory: Array<{recordId: string; primaryTopicSlug: string}> };
    expect(packet.assignment.inventory.map((row) => row.recordId).sort()).toEqual(program.inventory.filter((row) => row.primaryTopicSlug === slug).map((row) => row.recordId).sort());
    expect(packet.audit.map((row) => row.inventoryRecordId).sort()).toEqual(packet.assignment.inventory.map((row) => row.recordId).sort());
    expect(packet.audit.filter((row) => row.verdict === "Keep")).toHaveLength(2);
    expect(packet.audit.filter((row) => row.verdict === "Rewrite")).toHaveLength(10);
    expect(packet.audit.filter((row) => row.verdict === "Retire-and-replace")).toHaveLength(65);
    for (const before of packet.before) {
      expect(originalHashes.has(before.nodeSha256), before.node.questionVariantId).toBe(true);
      expect(originalHashes.has(before.questionSha256), before.question.id).toBe(true);
      expect(originalHashes.has(before.caseSha256), before.case.id).toBe(true);
      expect(sha(before.node)).toBe(before.nodeSha256);
      expect(before.snapshotNodeSha256).toContain(before.nodeSha256);
    }
    expect(packet.before.reduce((total, before) => total + before.finiteProfiles.length, 0)).toBe(272);
    expect(new Set(packet.before.flatMap((before) => before.finiteProfiles.map((profile) => profile.id))).size).toBe(176);
  });

  it("preserves prior accepted B2B39/B2B40 and original source inputs", () => {
    const shared = new Set(["packages/clinical-content/src/index.ts", "packages/clinical-content/src/synthetic-content.ts", "packages/clinical-content/src/question-ship-manifest.ts"]);
    for (const source of packet.assignment.currentSourceHashes.filter((source) => !shared.has(source.file))) {
      expect(createHash("sha256").update(readFileSync(new URL(`../../../${source.file}`, import.meta.url))).digest("hex"), source.file).toBe(source.sha256);
    }
    for (const frozen of packet.assignment.frozenPassReferences) {
      const clinicalCase = SYNTHETIC_CLINICAL_RELEASE.cases.find((candidate) => candidate.id === frozen.caseId)!;
      expect(sha(clinicalCase)).toBe(frozen.caseSha256);
      expect(sha(clinicalCase.decisionNodes.find((node) => node.id === frozen.nodeId))).toBe(frozen.nodeSha256);
      expect(ANSWER_CHOICE_TIMING_REGISTRY.find((entry) => entry.caseId === frozen.caseId && entry.nodeId === frozen.nodeId && entry.questionVariantId === frozen.questionVariantId)).toEqual(frozen.originalTimingEntry);
      expect(createHash("sha256").update(readFileSync(new URL(`../../../${frozen.reviewFile}`, import.meta.url))).digest("hex")).toBe(frozen.reviewFileSha256);
      expect(createHash("sha256").update(readFileSync(new URL(`../../../${frozen.decision}`, import.meta.url))).digest("hex")).toBe(frozen.decisionFileSha256);
    }
  });

  it("preserves the inherited holds and all registry/history identities", () => {
    expect(packet.assignment.concepts).toHaveLength(27);
    expect(packet.assignment.recordedHolds).toHaveLength(4);
    expect(packet.assignment.unkeyedDraftSlots.map((slot) => slot.recordId)).toEqual(["n4-slot-OR11", "n4-slot-OR12"]);
    expect(packet.assignment.withheldTeachingPoints).toHaveLength(2);
    expect(packet.assignment.holdScenarioMismatch.finding).toContain("no separate fluid cavity");
    const changed = current.conceptProposals.filter((concept) => concept.previousConceptId?.startsWith(`concept.topic.${slug}.`) && concept.id.endsWith(".v2"));
    expect(changed).toHaveLength(2);
    expect(changed.every((concept) => reviewed.concepts.some((old) => old.id === concept.previousConceptId))).toBe(true);
  });

  it("requires clinical review and retains qualitative author checks separate from independent verdicts", () => {
    for (const record of [...current.questions, ...current.conceptProposals, ...topic.ANORECTAL_TOPIC_SOURCES, ...topic.ANORECTAL_TOPIC_CLAIMS, ...current.caseReviews, ...current.statementMappings]) {
      expect(record.reviewStatus).toBe("needs_clinician_review");
      expect(record.aiAssistedDrafting).toBe(true);
      expect(record.lastClinicianReview).toBeNull();
    }
    for (const proposal of packet.proposals.filter((item) => item.status === "revised")) {
      const gate = proposal.manualAuthorGate;
      expect(gate.coverTheKeyCueAttack.length).toBeGreaterThan(100);
      expect(gate.twoConsequentialSteps.interpret.length).toBeGreaterThan(40);
      expect(gate.twoConsequentialSteps.apply.length).toBeGreaterThan(40);
      expect(gate.oneDefensibleKey.counterfactual.length).toBeGreaterThan(80);
      expect(proposal.choices.some((choice) => choice.id === gate.oneDefensibleKey.closestChoiceId && !choice.isCorrect)).toBe(true);
      expect(gate.repairRecord.length).toBeGreaterThan(100);
      expect(gate.pipelinePassed).toBe(false);
      expect(["moderate", "hard"]).toContain(gate.residentDifficulty.prediction);
      expect(proposal.visiblePriorContext).toEqual([]);
      const clinicalCase = current.cases.find((candidate) => candidate.id === proposal.caseId)!;
      expect(sha(clinicalCase)).toBe(proposal.exactVersion.caseSha256);
      expect(sha(clinicalCase.decisionNodes[0])).toBe(proposal.exactVersion.nodeSha256);
      expect(sha(current.questions.find((question) => question.id === proposal.questionVariantId))).toBe(proposal.exactVersion.questionSha256);
    }
  });

  it("retains clinic demographics and randomization without executable orders", () => {
    for (const clinicalCase of current.cases) {
      expect(clinicalCase.chiefComplaint!.split(/\s+/).length).toBeLessThanOrEqual(5);
      expect(clinicalCase.presentation).toContain("{patientName}");
      expect(clinicalCase.presentation).toContain(String(clinicalCase.prototypeDemographics!.ageYears));
      expect(clinicalCase.approvedInstantiationProfiles).toHaveLength(1);
      expect(clinicalCase.approvedInstantiationProfiles![0]!.prototypeDemographics).toEqual(clinicalCase.prototypeDemographics);
      for (const node of clinicalCase.decisionNodes) {
        expect(node.shuffleAnswers).toBe(true);
        expect(node.answerChoices).toHaveLength(3);
        expect(node.answerChoices.filter((choice) => choice.isCorrect)).toHaveLength(1);
        expect(node.stem).toContain("{patientName}");
        expect(node.resultGateAfter).toBeNull();
        expect(node.answerChoices.every((choice) => choice.serviceRequest === null)).toBe(true);
      }
    }
  });

  it("maps every current testing choice by exact identity and label and retains reviewed timing", () => {
    expect(current.timing).toEqual(packet.timingProposals);
    expect(current.orders).toHaveLength(13);
    expect(reviewed.timing).toHaveLength(22);
    for (const row of current.timing) {
      expect(answerChoiceTimingRegistryEntrySchema.safeParse(row).success).toBe(true);
      const node = current.nodes.find((node) => node.id === row.nodeId)!;
      const definition = packet.proposals.find((item) => item.nodeId === row.nodeId)!;
      if (row.classification.kind === "no_test") expect(definition.choices.every((choice) => choice.timingProfileId === null)).toBe(true);
      else {
        expect(row.classification.choices).toHaveLength(node.answerChoices.length);
        for (const choice of row.classification.choices) {
          expect(node.answerChoices.find((candidate) => candidate.id === choice.choiceId)?.label).toBe(choice.choiceLabel);
          if (choice.timing.kind === "test") expect(getDiagnosticTimingProfileMapping(choice.timing.timingProfileId)).toBeDefined();
        }
      }
      if (definition.conceptType === "workup") expect(definition.choices.every((choice) => choice.timingProfileId)).toBe(true);
    }
    for (const order of current.orders) {
      expect(order.disposition).toEqual({ kind: "not_executed", reason: "future_planned" });
      expect(order.serviceRequest).toBeNull();
      expect(order.resultGateAfter).toBeNull();
    }
  });

  it("resolves the chronology and prior-feedback issues in the revised standalone decisions", () => {
    const bySlug = (slug: string) => packet.proposals.find((item) => item.slug === slug)!;
    expect(bySlug("lis-after-treatment").choices.find((choice) => choice.isCorrect)?.label).toBe("Lateral internal sphincterotomy");
    expect(bySlug("persistent-bleeding-colonoscopy").currentUpdate).toContain("Bleeding stopped after hemorrhoid treatment");
    expect(bySlug("rectocele-repair-after-coordination").currentUpdate).toContain("A completed biofeedback course");
    expect(bySlug("rectocele-repair-after-coordination").explanation).toContain("STARR");
    expect(bySlug("rectocele-repair-after-coordination").currentUpdate).not.toContain("Repeat evacuation imaging");
    expect(bySlug("rectocele-dynamic-reassessment").explanation).not.toContain("omitted report");
    expect(bySlug("recurrent-fistula-mri").choices.some((choice) => choice.label === "Three-dimensional endoanal ultrasonography")).toBe(true);
    expect(bySlug("horseshoe-source-control").currentUpdate).toContain("patent left catheter can be retained");
    expect(bySlug("postbanding-sepsis").currentUpdate).toContain("remained low during initial fluid resuscitation");
  });

  it("reconciles full evidence mappings, preserved dates and safe source links", () => {
    const claims = new Map(ledger.claims.map((claim) => [claim.id, claim]));
    const sources = new Map(ledger.sources.map((source) => [source.id, source]));
    expect(claims.size).toBe(54);
    expect(sources.size).toBe(12);
    for (const question of current.questions) for (const id of question.supportingEvidenceClaimIds) {
      const claim = claims.get(id)!;
      expect(claim).toBeDefined();
      expect(claim.questionVariantIds).toContain(question.id);
      expect(claim.lastCheckedOn).toBe("2026-11-11");
      expect(claim.limitation.length).toBeGreaterThan(35);
      for (const sid of claim.sourceIds) expect(sources.get(sid)?.evidenceClaimIds).toContain(id);
    }
    for (const mapping of current.statementMappings) for (const assertion of mapping.assertions) {
      expect(assertion.claimIds.length).toBeGreaterThan(0);
      expect(assertion.claimIds.every((id) => claims.has(id))).toBe(true);
    }
    for (const link of topic.ANORECTAL_TOPIC_SOURCE_LINKS) {
      expect(link.target).toBe("_blank");
      expect(link.rel).toBe("noopener noreferrer");
      expect(link.referrerPolicy).toBe("no-referrer");
    }
    for (const source of ledger.sources) {
      expect(source.completeCitation.length).toBeGreaterThan(90);
      expect(source.authors.length).toBeGreaterThan(0);
      expect(source.reuseNotes).toBeTruthy();
      expect(source.authorityAssessment).toBeTruthy();
    }
  });
});

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { PROTOTYPE_BALANCE_RELEASE } from "@gamify-surgery/balance-config";
import { answerChoiceTimingRegistryEntrySchema, validateSyntheticClinicalRelease } from "./schema";
import { SYNTHETIC_CLINICAL_RELEASE } from "./synthetic-content";
import {
  BREAST_CANCER_TOPIC_AUTHOR_CHECKS as checks, BREAST_CANCER_TOPIC_AUTHORING_CONCEPTS as concepts,
  BREAST_CANCER_TOPIC_CASE_REVIEWS as caseReviews, BREAST_CANCER_TOPIC_CASES as cases,
  BREAST_CANCER_TOPIC_CLAIMS as claims, BREAST_CANCER_TOPIC_DEFINITIONS as definitions,
  BREAST_CANCER_TOPIC_MANIFEST as manifest, BREAST_CANCER_TOPIC_ORDER_PROPOSALS as orders,
  BREAST_CANCER_TOPIC_PREVIEW_RELEASE as preview, BREAST_CANCER_TOPIC_QUESTIONS as questions,
  BREAST_CANCER_TOPIC_SOURCE_LINKS as links, BREAST_CANCER_TOPIC_SOURCES as sources,
  BREAST_CANCER_TOPIC_STATEMENT_MAPPINGS as mappings, BREAST_CANCER_TOPIC_TIMING_ENTRIES as timings,
  BREAST_CANCER_TOPIC_REVIEW_DISPOSITIONS as dispositions, BREAST_CANCER_TOPIC_PARKS as parks,
  BREAST_CANCER_TOPIC_ROUND1_QUESTIONS as reviewedQuestions, BREAST_CANCER_TOPIC_ROUND1_CASES as reviewedCases,
} from "./question-topic-breast-cancer-20261111";

const root = new URL("../../../", import.meta.url);
const read = (p: string) => readFileSync(new URL(p, root), "utf8");
const hash = (v: unknown) => createHash("sha256").update(typeof v === "string" ? v : JSON.stringify(v)).digest("hex");
const packet = JSON.parse(read("docs/research/question-topic-breast-cancer-20261111.json"));
const ledger = JSON.parse(read("docs/research/sources-question-topic-breast-cancer-20261111.json"));
const program = JSON.parse(read("docs/research/question-topic-program-20261111.json"));
const nodes = cases.flatMap(c => c.decisionNodes);
const specs = definitions.flatMap(c => c.nodes);

describe("breast-cancer topic explicit-import authoring sidecar", () => {
  it("validates all clinic cases with existing runtime schema and no executed outside orders", () => {
    expect(validateSyntheticClinicalRelease(preview).cases).toHaveLength(12);
    expect(nodes).toHaveLength(13);
    expect(cases.every(c => c.requiredClinicalSetting === "clinic")).toBe(true);
    expect(nodes.every(n => n.resultGateAfter === null && n.answerChoices.every(a => a.serviceRequest === null))).toBe(true);
    expect(orders.every(o => o.executionScope === "clinic_review_of_outside_care")).toBe(true);
  });

  it("preserves independent review, manager acceptance and clinical approval as distinct states", () => {
    expect(manifest).toMatchObject({ pipelinePassed: false, managerAccepted: false, clinicalApproval: false, publicReleaseAuthorized: false, executableOrdersAdded: false });
    for (const x of [...questions, ...claims, ...sources, ...concepts, ...checks, ...caseReviews]) {
      expect(x.reviewStatus).toBe("needs_clinician_review");
      expect(x.lastClinicianReview).toBeNull();
    }
    expect(checks.every(c => !c.pipelinePassed && c.reviewerRole === "author_self_check")).toBe(true);
    expect(packet.clinicalApproval).toBe(false);
  });

  it("reconciles all primary-topic assignment rows, concepts and holds without omitting history", () => {
    const assigned = program.inventory.filter((r: any) => r.primaryTopicSlug === "breast-cancer");
    expect(packet.assignment.inventory).toEqual(assigned);
    for (const key of ["concepts", "caseAssignments", "nodeAssignments", "variantAssignments", "unkeyedDraftSlots", "withheldTeachingPoints"]) {
      expect(packet.assignment[key]).toEqual(program[key].filter((r: any) => r.primaryTopicSlug === "breast-cancer"));
    }
    expect(packet.audit.map((r: any) => r.recordId).sort()).toEqual(assigned.map((r: any) => r.recordId).sort());
    expect(new Set(packet.audit.map((r: any) => r.recordId)).size).toBe(50);
    expect(packet.assignment.concepts).toHaveLength(13);
    expect(packet.assignment.recordedHolds.map((h: any) => h.id)).toEqual(["review.n4.dcis-gland-removal-and-sentinel-sequence.v1"]);
    expect(packet.round1Snapshot.counts).toMatchObject({ audited: 50, kept: 7, rewritten: 7, retiredAndReplacedProposed: 36, new: 11, replacementDrafts: 2, authoredNodes: 20, reusedConcepts: 8, newMeanings: 10 });
    expect(packet.reviewResponse.counts).toMatchObject({ reviewed: 20, passPreserved: 7, revised: 6, parked: 7, activeNodes: 13, activeCases: 12 });
  });

  it("gives each exact old row a single verdict, supported replacement and hashed before context", () => {
    const available = new Set([...nodes.map(n => n.questionVariantId), ...packet.assignment.inventory.filter((r: any) => r.live).flatMap((r: any) => r.variantIds)]);
    for (const row of packet.audit) {
