describe("two returned salvage revisions", () => {
  it("rechecks only the two returned contexts and preserves the nine earlier accepted items", () => {
    const baseline = packet.salvageReviewResponseBaseline;
    expect(fileHash(baseline.reviewFile)).toBe(baseline.reviewFileSha256);
