      .toEqual(packet.salvageReviewResponses.map(row => row.currentNodeId).sort());
    expect(packet.currentReviewQueue.every(row => row.status === "salvage")).toBe(true);
    expect(packet.salvageBaseline.acceptedItems).toHaveLength(9);
    for (const before of packet.salvageBaseline.acceptedItems) {
