      expect(hash(packet.proposedNodes.find(item => item.questionVariantId === before.question.id))).toBe(before.definitionSha256);
      expect(salvageQuestions.some(item => item.id === before.question.id)).toBe(false);
    }
    expect(packet.itemStatuses).toEqual(packet.salvageBaseline.preSalvageItemStatuses);
  });

  it("keeps the three independent salvage PASS contexts and metadata exact", () => {
    const passed = packet.salvageReviewResponseBaseline.captured.filter(row => row.review.verdict === "PASS");
    expect(passed).toHaveLength(3);
    for (const before of passed) {
      expect(hash(salvageQuestions.find(item => item.id === before.question.id))).toBe(before.questionSha256);
      expect(hash(salvageNodes.find(item => item.id === before.node.id))).toBe(before.nodeSha256);
      expect(hash(salvageCases.find(item => item.id === before.clinicalCase.id))).toBe(before.caseSha256);
      expect(hash(salvageReviews.find(item => item.caseId === before.clinicalCase.id))).toBe(before.caseReviewSha256);
      expect(hash(packet.salvageCaseCompositionProposals.find(item => item.id === before.proposal.id))).toBe(before.proposalSha256);
      expect(hash(packet.salvageItems.find(item => item.caseId === before.clinicalCase.id))).toBe(before.itemSha256);
      expect(hash(salvageTimings.find(item => item.caseId === before.clinicalCase.id))).toBe(before.timingSha256);
      expect(packet.currentReviewQueue.some(item => item.caseId === before.clinicalCase.id)).toBe(false);
    }
    for (const claim of packet.salvageReviewResponseBaseline.ledger.evidenceClaims) {
      expect(ledger.evidenceClaims.find(item => item.id === claim.id)).toEqual(claim);
    }
  });

  it("materializes five standalone clinic cases with explicit new versions for the two repairs", () => {
    expect(validateSyntheticClinicalRelease(salvagePreview)).toMatchObject({ cases: salvageCases });
    expect(salvageCases).toHaveLength(5);
    expect(salvageNodes).toHaveLength(5);
    expect(salvageQuestions).toHaveLength(5);
    for (const item of salvageCases) {
      const response = packet.salvageReviewResponses.find(row => row.currentCaseId === item.id);
      const before = packet.salvageReviewResponseBaseline.captured.find(row => row.clinicalCase.id === (response?.previousCaseId ?? item.id))!;
      const node = item.decisionNodes[0]!;
      expect(item.decisionNodes).toHaveLength(1);
      expect(item.patientDisplayName).toBe(before.clinicalCase.patientDisplayName);
      expect(item.prototypeDemographics).toEqual(before.clinicalCase.prototypeDemographics);
      expect(node.primaryConceptId).toBe(before.node.primaryConceptId);
      expect(item.requiredClinicalSetting).toBe("clinic");
      expect(item.requiredCapabilityIds).toEqual([]);
      expect(item.presentation).toContain("{patientName}");
      expect(item.presentation).toContain("clinic");
      expect(item.presentation).toContain("outside");
      expect(item.presentation).toContain(`${item.prototypeDemographics!.ageYears}-year-old`);
      expect(item.chiefComplaint!.split(/\s+/).length).toBeLessThanOrEqual(5);
      expect(item.approvedInstantiationProfiles).toHaveLength(1);
      expect(item.approvedInstantiationProfiles![0]!.presentation).toBe(item.presentation);
      expect(item.approvedInstantiationProfiles![0]!.prototypeDemographics).toEqual(item.prototypeDemographics);
      expect(node.shuffleAnswers).toBe(true);
      expect(node.answerChoices.filter(choice => choice.isCorrect)).toHaveLength(1);
      expect(node.resultGateAfter).toBeNull();
      for (const choice of node.answerChoices.filter(answer => !answer.isCorrect)) {
        expect(node.terminalDispositions.filter(disposition => disposition.answerChoiceId === choice.id)).toHaveLength(1);
        expect(node.terminalDispositions.find(disposition => disposition.answerChoiceId === choice.id))
          .toMatchObject({ kind: "no_terminal_outcome", clinicalRationale: choice.rationale });
      }
      if (response) {
        expect(node.id).not.toBe(before.node.id);
        expect(node.questionVariantId).not.toBe(before.question.id);
        expect(item.id).not.toBe(before.clinicalCase.id);
        const proposal = packet.salvageItems.find(row => row.caseId === item.id)!;
        expect(proposal.status).toBe("salvage");
        expect(proposal.contextRecheckRequired).toBe(true);
        expect(proposal.independentPassForNewContext).toBe(false);
        expect(proposal.clinicalApproval).toBe(false);
        expect(proposal.manualAuthorGate).toHaveLength(5);
        expect(salvageQuestions.find(question => question.id === node.questionVariantId))
          .toMatchObject({ reviewStatus: "needs_clinician_review", lastClinicianReview: null });
      }
    }
  });

  it("maps revised choices to additive timing tuples and source-supported clinical claims", () => {
    const profiles = new Set(PROTOTYPE_BALANCE_RELEASE.answerChoiceTimingProfiles.map(item => item.id));
    expect(salvageTimings).toHaveLength(5);
