    expect(ledger.salvageMappingCheck.newEvidenceClaims).toBe(2);
    expect(ledger.salvageClaimToQuestionMappings).toHaveLength(40);
    for (const mapping of ledger.salvageClaimToQuestionMappings) {
      expect(mapping.questionVariantIds.slice().sort()).toEqual(salvageQuestions
        .filter(question => question.supportingEvidenceClaimIds.includes(mapping.claimId)).map(question => question.id).sort());
