      const item = salvageCases.find(row => row.id === entry.caseId)!;
      const mapping = ledger.salvageMappingCheck.statementMappings.find(row => row.caseId === item.id)!;
      expect(mapping.questionVariantId).toBe(entry.questionVariantId);
      for (const claimId of mapping.supportingEvidenceClaimIds) expect(ledger.evidenceClaims.some(claim => claim.id === claimId)).toBe(true);
      for (const choice of item.decisionNodes[0]!.answerChoices) {
        const order = salvageOrders.find(row => row.caseId === item.id && row.choiceId === choice.id)!;
        expect(order.questionVariantId).toBe(entry.questionVariantId);
        expect(order.choiceLabel).toBe(choice.label);
        expect(profiles.has(order.timingProfileId)).toBe(true);
        expect(order.disposition).toEqual({ kind: "not_executed", reason: "future_planned" });
        expect(choice.serviceRequest).toBeNull();
        if (entry.classification.kind === "test_choices") {
          const timing = entry.classification.choices.find(row => row.choiceId === choice.id)!;
          expect(timing.choiceLabel).toBe(choice.label);
          expect(timing.timing).toEqual({ kind: "test", timingProfileId: order.timingProfileId });
        }
      }
    }
    for (const before of packet.salvageReviewResponseBaseline.captured) {
      expect(packet.salvageReviewResponseBaseline.preResponseArtifacts.timingEntries.find(row => row.caseId === before.clinicalCase.id)).toEqual(before.timing);
    }
  });

  it("supplies treatment and diagnostic history without teaching the pre-answer interpretation", () => {
    const indefinite = salvageNodes.find(node => node.id.includes("indefinite-inflamed-biopsies"))!;
    expect(indefinite.currentUpdate).toMatch(/omeprazole once daily before breakfast/);
    expect(indefinite.currentUpdate).not.toMatch(/returns|original|repeat examination/i);
    expect(indefinite.answerChoices.filter(choice => choice.label.includes("before breakfast and dinner"))).toHaveLength(2);
    const reflux = salvageNodes.find(node => node.id.includes("unproven-reflux"))!;
    const visible = JSON.stringify({ exhibit: reflux.exhibit, stem: reflux.stem });
    expect(visible).toContain("first upper endoscopy");
    expect(visible).toContain("never undergone ambulatory reflux monitoring");
    expect(visible).not.toMatch(/unproven GERD|monitoring off therapy establishes|outside records were unavailable/i);
    for (const definition of packet.salvageRevisionDefinitions) {
      expect(definition.reasoning.steps).toHaveLength(2);
      expect(definition.reasoning.decidingObservation.length).toBeGreaterThan(50);
      expect(definition.reasoning.decisionChangingCounterfactual.length).toBeGreaterThan(60);
      expect(definition.choices.some(choice => choice.id === definition.reasoning.closestAlternativeChoiceId && !choice.isCorrect)).toBe(true);
      for (const choice of definition.choices) {
        expect(choice.rationale.length).toBeGreaterThan(30);
        for (const claimId of choice.evidenceClaimIds) expect(definition.supportingEvidenceClaimIds).toContain(claimId);
      }
      const clinicalText = [definition.currentUpdate, definition.task, definition.explanation,
        ...definition.choices.map(choice => choice.label)].join(" ");
      expect(clinicalText).not.toMatch(/\b\d+\s*(?:mg|minutes?|weeks?|months?)\b/i);
    }
  });
