const ledger = JSON.parse(read("docs/research/sources-question-topic-ethics-professionalism-20261111.json"));
const digest = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const program = JSON.parse(read("docs/research/question-topic-program-20261111.json"));

describe("ethics/professionalism topic authoring sidecar", () => {
  it("reconciles all 58 assigned contexts and 50 exact variant identities", () => {
