      expect(before.question.id).toBe(before.node.questionVariantId);
      expect(before.currentCase.decisionNodes.some((node: { id: string }) => node.id === before.node.id)).toBe(true);
      for (const context of before.retainedContextSerializations) {
        expect(context.node.questionVariantId).toBe(before.question.id);
        expect(packet.auditContexts.some((row: { recordId: string; semanticSha256: string }) =>
          row.recordId === before.recordId && row.semanticSha256 === context.semanticSha256)).toBe(true);
