  it("preserves one exact question/choice/key mapping per authored node", () => {
    for (const spec of specs) {
      const clinicalCase = cases.find(clinicalCase => clinicalCase.id === spec.caseId)!;
      const node = clinicalCase.decisionNodes.find(node => node.id === spec.nodeId)!;
      const question = questions.find(question => question.id === spec.questionVariantId)!;
      expect(node.primaryConceptId).toBe(spec.conceptId);
      expect(question.conceptId).toBe(spec.conceptId);
      expect(node.stem).toBe(question.stem);
      expect(node.explanation).toBe(question.explanation);
      expect(node.answerChoices.map(choice => [choice.id, choice.label, choice.isCorrect, choice.rationale]))
        .toEqual(question.answerChoices.map(choice => [choice.id, choice.label, choice.isCorrect, choice.rationale]));
      expect(node.answerChoices).toHaveLength(3);
      expect(node.answerChoices.filter(choice => choice.isCorrect)).toHaveLength(1);
      expect(node.answerChoices[0]!.isCorrect).toBe(false);
      expect(node.terminalDispositions).toHaveLength(clinicalCase.decisionNodes.at(-1) === node ? 2 : 0);
    }
  });
  it("maps all substantive fields and distractors bidirectionally to rights-reviewed claims", () => {
    expect(mappings).toHaveLength(26);
