      expect(spec.supportingEvidenceClaimIds.length).toBeGreaterThan(0);
      for (const claimId of spec.supportingEvidenceClaimIds) {
        expect(claimIds.has(claimId)).toBe(true);
        expect(ledger.claims.find((claim: { id: string }) => claim.id === claimId).questionVariantIds).toContain(spec.questionVariantId);
      }
      for (const choice of spec.choices) {
        expect(choice.rationale.length).toBeGreaterThan(20);
        expect(choice.temptation.length).toBeGreaterThan(20);
        expect(choice.counterfactual.length).toBeGreaterThan(20);
        for (const claimId of choice.evidenceClaimIds) expect(claimIds.has(claimId)).toBe(true);
      }
    }
    for (const claim of claims) for (const sourceId of claim.sourceIds) {
      expect(sourceIds.has(sourceId)).toBe(true);
      expect(sources.find(source => source.id === sourceId)!.evidenceClaimIds).toContain(claim.id);
    }
    expect(sources.some(source => /facs\.org|asahq\.org|PMC6729135/.test(source.officialUrl!))).toBe(false);
    expect(ledger.sourceTextStored).toBe(false);
  });
  it("requires concrete manual reasoning, cue, deletion and counterfactual records", () => {
    for (const spec of specs) {
      const gate = spec.manualAuthorGate;
      expect(gate.reasoningSteps).toHaveLength(2);
      for (const [field, value] of Object.entries(gate)) {
        if (field === "reasoningSteps") continue;
        expect(typeof value, `${spec.slug}.${field}`).toBe("string");
        expect((value as string).length, `${spec.slug}.${field}`).toBeGreaterThan(field === "closestAlternative" ? 12 : 20);
      }
    }
    const appreciation = specs.find(spec => spec.slug === "appreciation-assessment")!;
    expect(appreciation.currentUpdate).not.toMatch(/bracelet|protective object/i);
    expect(appreciation.manualAuthorGate.coverTheKey).toContain("assessment");
    expect(specs.some(spec => spec.slug === "error-care")).toBe(false);
