  it("classifies every exact choice without inventing orders, services or wait durations", () => {
    expect(timing).toHaveLength(26);
    expect(orders).toEqual([]);
    for (const entry of timing) {
      expect(answerChoiceTimingRegistryEntrySchema.safeParse(entry).success).toBe(true);
      expect(entry.classification).toEqual({ kind: "no_test" });
      const proposal = packet.timingProposals.find((row: { questionVariantId: string }) => row.questionVariantId === entry.questionVariantId);
      const node = cases.find(clinicalCase => clinicalCase.id === entry.caseId)!.decisionNodes.find(node => node.id === entry.nodeId)!;
      expect(proposal.choiceIdentityMapping.map((choice: { choiceId: string; choiceLabel: string }) => [choice.choiceId, choice.choiceLabel]))
        .toEqual(node.answerChoices.map(choice => [choice.id, choice.label]));
      expect(node.answerChoices.every(choice => choice.serviceRequest === null)).toBe(true);
      expect(node.stem + (node.currentUpdate ?? "")).not.toMatch(/\b\d+\s*(?:minutes?|hours?|days?)\b/i);
    }
  });
  it("keeps pediatric profiles and all runtime patient references consistent", () => {
    const pediatric = cases.filter(clinicalCase => clinicalCase.pediatricProfile);
    expect(pediatric).toHaveLength(0);
    const oldPediatric = packet.reviewRevision.before.cases.filter((clinicalCase: { pediatricProfile?: unknown }) => clinicalCase.pediatricProfile);
    expect(oldPediatric).toHaveLength(1);
    expect(oldPediatric[0].presentation).toContain("stays in the room throughout");
    for (const clinicalCase of cases) {
      const firstName = clinicalCase.patientDisplayName.split(" ")[0]!;
      for (const node of clinicalCase.decisionNodes) {
        expect(node.stem).toContain("{patientName}");
        expect(`${node.currentUpdate} ${node.stem} ${node.explanation}`).not.toMatch(new RegExp(`\\b${firstName}\\b`));
      }
