  it("freezes the exact reviewed versions and resolves every review row once", () => {
    const revision = packet.reviewRevision;
    expect(digest(revision.before)).toBe(revision.beforeSha256);
    expect(createHash("sha256").update(read(revision.reviewPath)).digest("hex")).toBe(revision.reviewSha256);
    expect(revision.review).toHaveLength(35);
    expect(revision.review.filter((row: { verdict: string }) => row.verdict === "PASS")).toHaveLength(0);
    expect(revision.dispositions).toHaveLength(35);
    expect(allProposals).toHaveLength(35);
    expect(parked).toHaveLength(9);
    for (const row of revision.dispositions) {
      const node = allProposals.find(node => node.questionVariantId === row.nextQuestionVariantId)!;
      const old = revision.before.draftNodes.find((old: { questionVariantId: string }) => old.questionVariantId === row.previousQuestionVariantId);
      expect(digest(old)).toBe(row.exactBeforeSha256);
      expect(digest(node)).toBe(row.exactAfterSha256);
      expect(node.revisionAttempt).toBe(1);
      expect(node.conceptId).toBe(old.conceptId);
      expect(node.questionVariantId).toMatch(/\.v2$/);
      for (const field of ["clarityIssues", "cues", "fairness", "suggestions"]) {
        const reviewRow = revision.review.find((candidate: { id: string }) => candidate.id === row.previousQuestionVariantId);
        expect(row.responses[field]).toHaveLength(reviewRow[field].length);
      }
      if (row.itemStatus === "parked") {
        expect(row.parkReason.length).toBeGreaterThan(80);
        expect(questions.some(question => question.id === node.questionVariantId)).toBe(false);
        expect(timing.some(entry => entry.questionVariantId === node.questionVariantId)).toBe(false);
      }
    }
  });
  it("repairs the failed sedation chronology without invalidating covered prior consent", () => {
    const spec = specs.find(spec => spec.slug === "reversible-delay")!;
    const clinicalCase = cases.find(clinicalCase => clinicalCase.id === spec.caseId)!;
    expect(clinicalCase.presentation).not.toContain("postponed");
    expect(spec.currentUpdate).toContain("Before premedication");
    expect(spec.currentUpdate).toContain("right-sided repair");
    expect(spec.currentUpdate).toContain("left side was absent");
    expect(spec.task).toContain("newly proposed left-sided");
    expect(spec.explanation).toContain("not automatically invalidated by sedation");
    expect(specs.every(spec => spec.itemStatus === "revised")).toBe(true);
    expect(cases.flatMap(clinicalCase => clinicalCase.decisionNodes).every(node =>
      node.answerChoices.every(choice => choice.id.includes(".r2.")))).toBe(true);
  });
});

