interface BeforeContext { caseSha256: string; nodeSha256: string; clinicalCase: { id: string }; origins: { file: string; export: string }[] }
interface AuditRow { recordId: string; verdict: string; reasons: string[]; replacementQuestionVariantIds: string[]; versionAudits: unknown[]; contextAudits: unknown[] }
const packet = JSON.parse(readFileSync(new URL("../../../docs/research/question-topic-statistics-20261111.json", import.meta.url), "utf8"));
const program = JSON.parse(readFileSync(new URL("../../../docs/research/question-topic-program-20261111.json", import.meta.url), "utf8"));
const ledger = JSON.parse(readFileSync(new URL("../../../docs/research/sources-question-topic-statistics-20261111.json", import.meta.url), "utf8"));
const independentReviewBytes = readFileSync(new URL("../../../docs/research/question-topic-statistics-review-20261111.json", import.meta.url));
const independentReview = JSON.parse(independentReviewBytes.toString("utf8"));
const digest = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const words = (text: string) => text.trim().split(/\s+/u).filter(Boolean).length;
function definition(slug: string) {
  const d = STATISTICS_TOPIC_DEFINITIONS.find(d => d.slug === slug);
  if (!d) throw new Error(slug);
  return d;
}
function correct(slug: string) { return definition(slug).options[0]!.label; }
function cells(slug: string): number[][] {
  const e = definition(slug).exhibit;
  if (e.kind !== "table") throw new Error(slug);
  return e.cells.map(row => row.map(Number));
}
function values(slug: string): string[] {
  const e = definition(slug).exhibit;
  if (e.kind !== "keyValue") throw new Error(slug);
  return e.items.map(x => x.value);
}
function exhibitText(slug: string) {
  const e = definition(slug).exhibit;
  if (e.kind === "table") return [e.caption, ...e.rowHeaders, ...e.columnHeaders, ...e.cells.flat()].join(" ");
  if (e.kind === "keyValue") return [e.caption, ...e.items.flatMap(x => [x.label, x.value])].join(" ");
  throw new Error("Methods sidecar uses no image or promised external asset.");
}

