  it("independently recomputes the diagnostic table keys and closest denominator errors", () => {
    const npv = cells("negative-predictive-value");
    const [fn, tn] = npv[1] as [number, number];
    expect(correct("negative-predictive-value")).toBe(`${100 * tn / (tn + fn)}%`);
    expect(Math.round(100 * tn / (tn + npv[0]![1]!))).toBe(67);
    const lr = cells("positive-likelihood-ratio");
    const sum = (a: number[]) => a.reduce((n, v) => n + v, 0);
    const ratio = (lr[0]![0]! / sum(lr[0]!)) / (lr[1]![0]! / sum(lr[1]!));
    expect(correct("positive-likelihood-ratio")).toBe(ratio.toFixed(1));
    expect(lr[0]![0]! / lr[1]![0]!).toBe(2);
    const prior = Number(values("post-test-probability")[0]!.match(/\d+/)![0]) / 100;
    const likelihood = Number(values("post-test-probability")[1]!.match(/\d+/)![0]);
    const odds = prior / (1 - prior) * likelihood;
    expect(correct("post-test-probability")).toBe(`${100 * odds / (1 + odds)}%`);
    expect(prior * likelihood).toBe(0.8);
  });

  it("independently recomputes absolute harm, relative benefit and standardization", () => {
    const rates = values("number-needed-to-harm")[0]!.match(/\d+(?=%)/g)!.map(Number);
