    const risks = values("relative-risk-reduction")[0]!.match(/\d+(?=%)/g)!.map(Number);
    expect(correct("relative-risk-reduction")).toBe(`${100 * (risks[0]! - risks[1]!) / risks[0]!}%`);
    const e = definition("standardized-risk").exhibit;
    if (e.kind !== "table") throw new Error("table required");
    const weighted = e.cells.reduce((n, row) => n + Number.parseFloat(row[0]!) * Number.parseFloat(row[1]!) / 100, 0);
    expect(correct("standardized-risk")).toBe(`${weighted}%`);
    expect((Number.parseFloat(e.cells[0]![0]!) + Number.parseFloat(e.cells[1]![0]!)) / 2).toBe(20);
  });

