  it("re-solves equivalence endpoints, linked pairs, survival risk sets and counterfactuals", () => {
    const eq = values("equivalence-interval")[0]!;
    expect(eq).toContain("90% CI -1 to +3 days");
    const numeric = eq.match(/[+-]?\d+(?:\.\d+)?/g)!.map(Number);
    const lowerMargin = numeric[1]!, upperMargin = numeric[2]!;
    const classify = (lower: number, upper: number) => lower > lowerMargin && upper < upperMargin ? "equivalent"
      : lower > upperMargin || upper < lowerMargin ? "outside" : "inconclusive";
    expect(classify(numeric.at(-2)!, numeric.at(-1)!)).toBe("inconclusive");
    expect(correct("equivalence-interval")).toBe("Evidence is inconclusive");
    expect(classify(-1, 1)).toBe("equivalent");
    expect(classify(3, 4)).toBe("outside");
    expect(classify(-4, -3)).toBe("outside");
    const paired = cells("discordant-pairs");
    const discordant = paired[0]![1]! + paired[1]![0]!;
    expect(correct("discordant-pairs")).toBe(`${discordant} pairs`);
    expect(paired[0]![0]! + paired[1]![1]!).toBe(70);
    const cohort = values("kaplan-meier-step")[0]!;
    expect(cohort).toContain("At month 1, two are censored");
    expect(cohort).toContain("At month 2, two deaths occur");
    const remaining = 10 - 2;
    expect(correct("kaplan-meier-step")).toBe(`${100 * (remaining - 2) / remaining}%`);
    expect(100 * (10 - 2) / 10).toBe(80); // moving censoring after deaths changes the risk set
    expect(correct("right-censoring")).toBe("Censored at 12 months");
    expect(correct("zero-correlation")).toBe("Linear association is absent in the sample");
  });

