  it("re-solves the raw baseline-stratum comparison and decision-changing counterfactuals", () => {
    const d = definition("stratified-confounding");
    expect(d.exhibit.kind).toBe("table");
    if (d.exhibit.kind !== "table") throw new Error("Raw table required");
    const data = d.exhibit.cells.map(row => row.map(cell => cell.split("/").map(Number) as [number, number]));
    const risks = data.map(row => row.map(([events, total]) => events / total));
    expect(risks).toEqual([[0.2, 0.2], [0.6, 0.6]]);
    expect(risks.map(row => row[0]! / row[1]!)).toEqual([1, 1]);
    const crude = [0, 1].map(column => data.reduce((sum, row) => sum + row[column]![0], 0) / data.reduce((sum, row) => sum + row[column]![1], 0));
    expect(crude).toEqual([0.56, 0.24]);
    expect(risks.map((_, column) => 0.5 * risks[0]![column]! + 0.5 * risks[1]![column]!)).toEqual([0.4, 0.4]);
    expect(d.exhibit.caption).toContain("severity recorded before pathway selection");
    expect(exhibitText(d.slug)).not.toMatch(/common cause|confound|effect modification|standardiz|risk ratio/i);
