    expect(labels.filter(label => label.includes("Linear"))).toHaveLength(2);
  });
});

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { SYNTHETIC_CLINICAL_RELEASE as live } from "./synthetic-content";
import { QUESTION_SHIP_MANIFEST as manifest } from "./question-ship-manifest";
import {
  beforeProgramBatch3AcceptanceManifest,
  beforeProgramBatch3AcceptanceRelease,
  beforeProgramBatch3AcceptanceSource,
} from "./question-program-batch3-acceptance-test-support";
import {
  answerChoiceTimingRegistryEntrySchema,
  syntheticClinicalReleaseSchema,
} from "./schema";
import * as topic from "./question-topic-surgical-infection-antibiotics-20261111";

const packet = topic.SURGICAL_INFECTION_TOPIC_PACKET;
const ledger = topic.SURGICAL_INFECTION_TOPIC_LEDGER;
const questions = topic.SURGICAL_INFECTION_TOPIC_QUESTIONS;
const nodes = topic.SURGICAL_INFECTION_TOPIC_NODES;
const cases = topic.SURGICAL_INFECTION_TOPIC_CASES;
const sha = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const readRoot = (path: string) => readFileSync(new URL(`../../../${path}`, import.meta.url), "utf8");

describe("surgical infection and antibiotics authoring sidecar", () => {
  it("imports through its explicit entry point with the captured default release intact", () => {
    const current = packet.reviewRound.currentBaseline;
    // Verify the authorized whole acceptance delta before reconstructing this packet's v11 epoch.
    const priorLive = beforeProgramBatch3AcceptanceRelease(live);
    const priorManifest = beforeProgramBatch3AcceptanceManifest(manifest);
    expect(packet.assignment.baseline).toMatchObject({ manifestId: "question-ship.2026-11-10.v9",
      manifestRows: 145, cases: 1151, nodes: 1462, concepts: 610 });
    expect(priorManifest.id).toBe(current.manifestId);
    expect(priorManifest.accepted).toHaveLength(current.manifestRows);
    expect(priorLive.cases).toHaveLength(current.cases);
    expect(priorLive.cases.flatMap((clinicalCase) => clinicalCase.decisionNodes)).toHaveLength(current.nodes);
    expect(priorLive.concepts).toHaveLength(current.concepts);
    expect(sha(priorLive)).toBe(current.liveReleaseSha256);
    expect(sha(priorManifest)).toBe(current.manifestSha256);
    for (const preserved of packet.validation.latestReadOnlyBaseline.assignedLivePreservation) {
      expect(preserved.matchesCapturedCase).toBe(true);
      expect(sha(priorLive.cases.find((clinicalCase) => clinicalCase.id === preserved.caseId)))
        .toBe(preserved.currentCaseSha256);
    }
    const liveIds = new Set(live.cases.flatMap((clinicalCase) =>
      clinicalCase.decisionNodes.map((node) => node.questionVariantId)));
    const accepted = new Set(packet.salvageRound.acceptedPreservation.map((row) => row.questionVariantId));
    for (const question of questions) expect(liveIds.has(question.id)).toBe(accepted.has(question.id));
  });

  it("parses the authored clinic preview using the existing release schema", () => {
    expect(syntheticClinicalReleaseSchema.safeParse(topic.SURGICAL_INFECTION_TOPIC_SOURCE_RELEASE).success).toBe(true);
    expect(questions).toHaveLength(13);
    expect(nodes).toHaveLength(13);
    expect(cases).toHaveLength(10);
    expect(topic.SURGICAL_INFECTION_TOPIC_CONCEPTS).toHaveLength(13);
    expect(topic.SURGICAL_INFECTION_TOPIC_INTEGRATION.managerAcceptance).toBeNull();
  });

  it("retains the complete primary assignment and related cross-topic ownership", () => {
    const program = JSON.parse(readRoot("docs/research/question-topic-program-20261111.json"));
    for (const [key, rows] of Object.entries(packet.assignment.completeAssignedRows)) {
      expect(rows).toEqual(program[key].filter((row: { primaryTopicSlug: string }) =>
        row.primaryTopicSlug === packet.assignment.slug));
    }
    expect(packet.assignment.relevantIdentityReuseNotes.some((row) =>
      row.primaryTopicSlug === "quality-safety-systems")).toBe(true);
    expect(packet.assignment.baseline.relevantDrift).toEqual([]);
  });

  it("pins all inspected source inputs and the exact authoring standard", () => {
    for (const input of packet.reviewRound.currentBaseline.inputHashes) {
      const priorText = beforeProgramBatch3AcceptanceSource(input.file, readRoot(input.file));
      expect(createHash("sha256").update(priorText).digest("hex"))
        .toBe(input.sha256);
    }
    for (const input of packet.assignment.baseline.inputHashChecks) {
      if (input.snapshotSha256) expect(input.matchesSnapshot).toBe(true);
