  it("reconciles all 24 verdicts and all 25 captured case contexts", () => {
    const audit = packet.completeAudit.rows;
    expect(audit).toHaveLength(24);
    expect(new Set(audit.map((row) => row.inventoryRecordId)).size).toBe(24);
    expect(audit.map((row) => row.inventoryRecordId).sort()).toEqual(
      packet.assignment.completeAssignedRows.inventory.map((row) => row.recordId).sort());
