    expect(packet.proposedQuestions.some((row) => row.slug === "residual-incisional-pocket")).toBe(false);
    const retained = packet.retainedReplacementProposals[0]!;
    expect(retained.questionVariantId).toBe("question.n2.prophylaxis-versus-ssi-source-control.v2");
    expect(retained.admissionState).toBe("draft parked");
    expect(retained.beforeQuestionHashes).toEqual(audit
      .find((row) => row.inventoryRecordId === retained.inventoryRecordId)!.beforeQuestionHashes);
    for (const row of audit) {
      expect(row.reasons.length).toBeGreaterThan(75);
      expect(row.beforeQuestionHashes.length).toBeGreaterThan(0);
      expect(row.contextAudits.length).toBeGreaterThan(0);
      for (const id of row.replacementQuestionIds) {
        expect(questions.some((question) => question.id === id) ||
          packet.retainedReplacementProposals.some((proposal) => proposal.questionVariantId === id) ||
          packet.reviewRound.parkedItems.some((proposal) => proposal.questionVariantId === id)).toBe(true);
      }
      if (row.verdict !== "Keep") expect(row.replacementQuestionIds.length).toBeGreaterThan(0);
    }
  });

  it("preserves exact before snapshots and the accepted N4 PASS reference", () => {
    for (const before of [...packet.beforeSnapshots.questions, ...packet.beforeSnapshots.cases]) {
      expect(sha(before.value)).toBe(before.sha256);
    }
    const frozen = packet.assignment.frozenPassAndClinicalApprovalReferences[0]!;
