  it("exposes the consequential medication and compartment records without supplying the decision", () => {
    const authored = packet.salvageRevision.questions;
    const duration = authored.find((row) => row.slug === "adequate-control-duration")!;
    expect(duration.currentUpdate).toContain("four full days");
    expect(duration.currentUpdate).toContain("no bloodstream infection");
