    expect(mrsa.currentUpdate + JSON.stringify(mrsa.exhibit)).not.toContain("cefazolin");
    expect(mrsa.answerChoices.some((row) => row.label === "Proceed to incision without another antimicrobial"))
      .toBe(true);
    const pelvic = authored.find((row) => row.slug === "pelvic-source-route")!;
    expect(pelvic.stem).not.toContain("source-control");
    expect(pelvic.currentUpdate).toContain("incisional pain and redness diminished");
    expect(pelvic.exhibit?.kind).toBe("table");
    expect(JSON.stringify(pelvic.exhibit)).toContain("intact fascia");
    expect(JSON.stringify(pelvic.exhibit)).toContain("rim-enhancing fluid");
    expect(pelvic.explanation).toContain("does not exclude an occult communication");
