let sequence = 0;
const onlyCases = (cases: SyntheticClinicalCase[]): DomainContext => ({ ...context,
  clinicalRelease: { ...context.clinicalRelease, cases } });
function vacantState(): GameState {
  const state = createPediatricChartsQaState(context);
  state.encounters = {}; state.pediatricFamilies = {}; state.retailExternalActors = [];
  state.openChartEncounterId = null; state.attendedEncounterId = null;
  state.paused = false; state.nextRoutineArrivalTick = 0;
  return state;
}
function apply(state: GameState, command: GameCommand, ctx = context): GameState {
  const next = gameReducer(state, command, ctx);
  expect(next.operationReceipts[command.operationId], command.operationId).toMatchObject({ status: "applied" });
  return next;
}
function pairTogether(state: GameState): void {
  const child = state.encounters[encounterId]!;
  const family = pediatricFamilyForActor(state, "encounter", encounterId)!;
  const parent = state.retailExternalActors.find(actor => actor.id === family.parentActorId)!;
  expect(pediatricRoomAtPoint(state, context, child.patientLocation)?.id).toBe(pediatricRoomAtPoint(state, context, parent.location)?.id);
  if (!child.patientLocation) expect(parent.location).toBeNull();
}
function until(state: GameState, predicate: (state: GameState) => boolean): GameState {
  for (let i = 0; i < 240 && !predicate(state); i++) {
    state = apply({ ...state, paused: false }, { type: "ADVANCE_TICK", operationId: `m7.tick.${sequence++}` });
    pairTogether(state);
  }
  expect(predicate(state), JSON.stringify(state.encounters[encounterId])).toBe(true);
  return state;
}

describe("M7 scored pediatric prototype admission", () => {
  it.each(PEDIATRIC_CLINIC_CASES.map(clinicalCase => [clinicalCase.id, clinicalCase] as const))
    ("freezes the constrained child, exact still and named parent for %s", (_id, clinicalCase) => {
      const familyContext = PEDIATRIC_CLINIC_FAMILY_CONTEXTS.find(family => family.caseId === clinicalCase.id)!;
      const state = createPediatricChartsQaState(context, clinicalCase.id);
      const encounter = state.encounters[encounterId]!;
      const family = pediatricFamilyForActor(state, "encounter", encounterId)!;
      const parent = state.retailExternalActors.find(actor => actor.id === family.parentActorId)!;
      expect(encounter.patientDisplayName).toBe(familyContext.childName);
      expect(encounter.frozenCase.patientDisplayName).toBe(familyContext.childName);
      expect(encounter.frozenCase.prototypeDemographics).toEqual(familyContext.prototypeDemographics);
      expect(encounter.frozenCase.selectedInstantiationProfileId).toBe(familyContext.profileId);
      expect(encounter.frozenCase.presentation).toBe(clinicalCase.presentation);
      expect(encounter.frozenCase.decisionNodes[0]!.stem).toBe(clinicalCase.decisionNodes[0]!.stem);
      expect(encounter.patientAppearance.stillId).toBe(familyContext.childStillId);
      expect(encounter.patientAppearance.patientIdentityId).toBeUndefined();
      expect(pediatricStillEligibleEntries(familyContext.prototypeDemographics.sexLabel, familyContext.prototypeDemographics.ageYears)
        .some(entry => entry.stillId === encounter.patientAppearance.stillId)).toBe(true);
      expect(parent.displayName).toBe(familyContext.parentName);
      const parentStill = characterStillCatalogEntryById(parent.appearance.stillId);
      expect(parentStill && "compatibleSexLabel" in parentStill ? parentStill.compatibleSexLabel : null)
        .toBe(familyContext.parentRelationship === "mother" ? "Female" : "Male");
      expect(state.retailExternalActors).toHaveLength(1);
      expect(Object.values(state.pediatricFamilies!)).toHaveLength(1);
      expect(state.serviceOperations).toEqual([]);
      expect(state.levelFourCompletion?.pediatricVisitWithParent).toBeFalsy();
      const restored = deserializeGameState(serializeGameState(state), context);
      expect(restored.encounters).toEqual(state.encounters);
      expect(restored.pediatricFamilies).toEqual(state.pediatricFamilies);
      expect(restored.retailExternalActors).toEqual(state.retailExternalActors);
    });

  it("randomizes every node while retaining exact choice meaning and the child name even with an override", () => {
    let nonFirstKeys = 0;
    for (const clinicalCase of PEDIATRIC_CLINIC_CASES) {
      let state = vacantState();
      const histories = structuredClone(state.learningHistories);
      state = apply(state, { type: "ADMIT_PATIENT", operationId: `m7.shuffle.${clinicalCase.id}`, encounterId,
        caseId: clinicalCase.id, arrivalClass: "routine", patientDisplayName: "Override attempt" });
      const encounter = state.encounters[encounterId]!;
      expect(encounter.patientDisplayName).toBe(clinicalCase.patientDisplayName);
      const choices = encounter.frozenCase.decisionNodes[0]!.answerChoices;
      expect([...choices].sort((a, b) => a.id.localeCompare(b.id)))
        .toEqual([...clinicalCase.decisionNodes[0]!.answerChoices].sort((a, b) => a.id.localeCompare(b.id)));
      nonFirstKeys += choices.findIndex(choice => choice.isCorrect) > 0 ? 1 : 0;
      expect(state.learningHistories).toEqual(histories);
    }
    expect(nonFirstKeys).toBeGreaterThan(0);
  });

  it("requires Level 4 and a real operational Pediatric Examination for explicit and automatic admission and availability", () => {
    const clinicalCase = PEDIATRIC_CLINIC_CASES[0]!;
    const ctx = onlyCases([clinicalCase]);
    const command: GameCommand = { type: "ADMIT_PATIENT", operationId: "m7.gate", encounterId,
      caseId: clinicalCase.id, patientDisplayName: clinicalCase.patientDisplayName, arrivalClass: "routine" };
    for (const gate of ["level3", "no-exam", "no-access", "wrong-room"] as const) {
      const state = vacantState();
      if (gate === "level3") state.facilityLevel = 3;
      if (gate === "no-exam") state.rooms = state.rooms.filter(room => room.id !== "room.peds.exam");
      if (gate === "no-access") state.doors = state.doors.filter(door => door.roomId !== "room.peds.exam");
      if (gate === "wrong-room") {
        state.rooms.find(room => room.id === "room.peds.exam")!.roomDefinitionId = "room.examination";
        // Even a separately supplied same-named capability is insufficient.
        ctx.balanceRelease = { ...context.balanceRelease, facility: { ...context.balanceRelease.facility,
          roomDefinitions: context.balanceRelease.facility.roomDefinitions.map(room => room.id === "room.examination"
            ? { ...room, capabilityIds: [...room.capabilityIds, "capability.pediatric_examination"] } : room) } };
      }
      const rejected = gameReducer(state, command, ctx);
      expect(rejected.operationReceipts[command.operationId]?.status, gate).toBe("rejected");
      expect(rejected.encounters).toEqual({});
      expect(getRoutinePatientAvailability(state, NOW, ctx).reason, gate).toBe(gate === "level3" ? "content_unavailable" : "capabilities_unavailable");
      const advanced = apply(state, { type: "ADVANCE_TICK", operationId: `m7.auto.${gate}`, advancedAtRealMs: NOW }, ctx);
      expect(advanced.encounters).toEqual({});
    }
    const state = vacantState();
    expect(getRoutinePatientAvailability(state, NOW, context).reason).toBe("available");
    const advanced = apply(state, { type: "ADVANCE_TICK", operationId: "m7.auto.available", advancedAtRealMs: NOW }, onlyCases([clinicalCase]));
    const child = Object.values(advanced.encounters)[0]!;
    expect(child.frozenCase.id).toBe(clinicalCase.id);
    expect(child.patientDisplayName).toBe(clinicalCase.patientDisplayName);
    expect(pediatricFamilyForActor(advanced, "encounter", child.id)).toBeTruthy();
    expect(PROTOTYPE_DOMAIN_CONTEXT.balanceRelease.facility.maximumPlayableLevel).toBe(5);
    expect(PROTOTYPE_DOMAIN_CONTEXT.balanceRelease.facility.stageDefinitions.find(stage => stage.level === 3)?.nextFacilityLevel).toBe(4);
  });

  it.each(["service.mrcp", "service.endoscopy", "service.sedation", "income.ambulatory_operation", "income.wound_procedure"])
    ("withholds a broken distractor promise for %s", serviceId => {
      const clinicalCase = structuredClone(PEDIATRIC_CLINIC_CASES[0]!);
      clinicalCase.decisionNodes[0]!.answerChoices[1]!.serviceRequest = { serviceId };
      const ctx = onlyCases([clinicalCase]);
      const state = vacantState();
      expect(clinicalCaseHasSupportedPatientSemantics(clinicalCase)).toBe(false);
      expect(getRoutinePatientAvailability(state, NOW, ctx).reason).toBe("content_unavailable");
      const rejected = gameReducer(state, { type: "ADMIT_PATIENT", operationId: "m7.unsupported", encounterId,
        caseId: clinicalCase.id, patientDisplayName: clinicalCase.patientDisplayName, arrivalClass: "routine" }, ctx);
      expect(rejected.operationReceipts["m7.unsupported"]?.status).toBe("rejected");
      expect(rejected.encounters).toEqual({});
      expect(rejected.pediatricFamilies).toEqual({});
    });

  it("applies semantic release gating even if stage/capability fields drift, and rejects a mismatched frozen child profile", () => {
    const clinicalCase = structuredClone(PEDIATRIC_CLINIC_CASES[0]!);
    clinicalCase.earliestFacilityStage = 0; clinicalCase.requiredCapabilityIds = [];
    const state = vacantState(); state.facilityLevel = 3;
    expect(getClinicalCaseEligibilityIssue(state, clinicalCase, context)).toBe("This patient becomes eligible at Level 4.");
    state.facilityLevel = 4; state.rooms = state.rooms.filter(room => room.id !== "room.peds.exam");
    expect(getClinicalCaseEligibilityIssue(state, clinicalCase, context)).toBe("This patient requires an operational Pediatric Examination Room.");
    clinicalCase.approvedInstantiationProfiles![0]!.prototypeDemographics!.ageYears = 8;
    expect(clinicalCaseHasSupportedPatientSemantics(clinicalCase)).toBe(false);
  });

  it("keeps a due adult review of the unchanged concept available before L4 and preserves old frozen charts/history", () => {
    const conceptId = "concept.umbilical-epigastric-hernia.clinical-recognition";
    const adultCases = SYNTHETIC_CLINICAL_RELEASE.cases.filter(clinicalCase => !clinicalCase.pediatricProfile &&
      clinicalCase.decisionNodes.length === 1 && clinicalCase.decisionNodes[0]!.primaryConceptId === conceptId);
    expect(adultCases.length).toBeGreaterThan(0);
    const state = createInitialGameState();
    const frozen = structuredClone(state.encounters);
    state.facilityLevel = 3; state.encounters = {}; state.openChartEncounterId = null; state.attendedEncounterId = null;
    state.paused = false; state.nextRoutineArrivalTick = 0;
    const adult = adultCases[0]!; const node = adult.decisionNodes[0]!;
    const review = applyFsrsReview(createNewFsrsCard(0), "Good", 1_000, context.balanceRelease.learning);
    state.learningHistories[conceptId] = { conceptId, card: { ...review.card, dueAtMs: NOW }, reviews: [{
      id: "review.old.midline", encounterId: "encounter.old.midline", decisionNodeId: node.id,
      questionVariantId: node.questionVariantId, patientPresentationVariantId: adult.patientPresentationVariantId,
      primaryConceptId: conceptId, answerChoiceId: node.answerChoices.find(choice => choice.isCorrect)!.id,
      correct: true, rating: "Good", reviewedAtMs: 1_000, facilityTick: 0, schedulerLog: review.log,
    }] };
    const histories = structuredClone(state.learningHistories);
    const ctx = onlyCases([...adultCases, ...PEDIATRIC_CLINIC_CASES]);
    expect(getRoutinePatientAvailability(state, NOW, ctx).reason).toBe("available");
    const eligible = ctx.clinicalRelease.cases.filter(clinicalCase => getClinicalCaseEligibilityIssue(state, clinicalCase, ctx) === null);
    expect(selectRoutineClinicalCase(state, eligible, NOW)).toMatchObject({ kind: "due_review", selectedConceptId: conceptId });
    const advanced = apply(state, { type: "ADVANCE_TICK", operationId: "m7.old.due", advancedAtRealMs: NOW }, ctx);
    const admitted = Object.values(advanced.encounters)[0]!;
    expect(admitted.frozenCase.pediatricProfile).toBeUndefined();
    expect(admitted.frozenCase.decisionNodes[0]!.primaryConceptId).toBe(conceptId);
    expect(advanced.learningHistories).toEqual(histories);
    expect(SYNTHETIC_CLINICAL_RELEASE.concepts.filter(concept => concept.id === conceptId)).toHaveLength(1);
    const oldSave = { ...state, paused: true, encounters: frozen };
    const restored = deserializeGameState(serializeGameState(oldSave));
    expect(restored.encounters).toEqual(frozen);
    expect(restored.learningHistories).toEqual(histories);
  });

  it.each(["case.pediatric-clinic.intermittent-groin-swelling", "case.pediatric-clinic.epigastric-standing-bulge",
    "case.pediatric-clinic.pilonidal-mild-cleft-symptoms"])
    ("routes a scored visit with its parent, records M5's witness once and survives reload/retirement: %s", caseId => {
      let state = createPediatricChartsQaState(context, caseId);
      const identity = structuredClone([state.encounters[encounterId]!.patientAppearance,
        state.retailExternalActors[0]!.appearance, state.retailExternalActors[0]!.displayName]);
      state = until(state, value => value.encounters[encounterId]!.checkInStatus === "checked_in" &&
        !value.encounters[encounterId]!.patientMovement);
      const family = pediatricFamilyForActor(state, "encounter", encounterId)!;
      expect(family.reservation?.roomInstanceId).toBe("room.peds.wait");
      expect(family.reservation?.parentSeatId?.startsWith("kid")).toBe(false);
      expect(family.reservation?.childSeatId?.startsWith("kid")).toBe(state.encounters[encounterId]!.frozenCase.prototypeDemographics!.ageYears < 10);
      state = deserializeGameState(serializeGameState(state), context); pairTogether(state);
      state = apply(state, { type: "OPEN_CHART", operationId: `m7.open.${caseId}`, encounterId });
      state = until(state, value => pediatricPairAtReservation(value, pediatricFamilyForActor(value, "encounter", encounterId)!) &&
        value.encounters[encounterId]!.assignedRoomInstanceId === "room.peds.exam");
      expect(pediatricFamilyForActor(state, "encounter", encounterId)!.reservation)
        .toMatchObject({ roomInstanceId: "room.peds.exam", childSeatId: "table:patient", parentSeatId: "parentChair" });
      expect(state.levelFourCompletion?.pediatricVisitWithParent).toBeFalsy();
      state = deserializeGameState(serializeGameState(state), context);
      const node = state.encounters[encounterId]!.frozenCase.decisionNodes[0]!;
      state = apply(state, { type: "SUBMIT_ANSWER", operationId: `m7.answer.${caseId}`, encounterId,
        decisionNodeId: node.id, answerChoiceId: node.answerChoices.find(choice => choice.isCorrect)!.id, reviewedAtMs: NOW });
      expect(state.levelFourCompletion?.pediatricVisitWithParent).toEqual({ serviceOperationId: null, encounterId,
        incomeLineId: "income.pediatric_consult", completedAtFacilityTick: state.facilityTick,
        parentActorId: family.parentActorId });
      expect(state.learningHistories[node.primaryConceptId]!.reviews).toHaveLength(1);
      expect(state.serviceOperations).toEqual([]);
      expect([state.encounters[encounterId]!.patientAppearance, state.retailExternalActors[0]!.appearance,
        state.retailExternalActors[0]!.displayName]).toEqual(identity);
      const witness = structuredClone(state.levelFourCompletion);
      const income = structuredClone(state.serviceIncomeReceipts);
      state = apply(state, { type: "ACKNOWLEDGE_TERMINAL_FEEDBACK", operationId: `m7.ack.${caseId}`, encounterId });
      state = apply(state, { type: "CLOSE_CHART", operationId: `m7.close.${caseId}`, encounterId });
      state = until(state, value => value.encounters[encounterId]!.patientLocation === null);
      expect(state.levelFourCompletion).toEqual(witness);
      expect(state.serviceIncomeReceipts).toEqual(income);
      state.encounters = {}; state.pediatricFamilies = {}; state.retailExternalActors = [];
      state.rooms = state.rooms.filter(room => !["room.peds.wait", "room.peds.exam"].includes(room.id));
      state.doors = state.doors.filter(door => !["room.peds.wait", "room.peds.exam"].includes(door.roomId));
      state = deserializeGameState(serializeGameState(state), context);
      expect(state.levelFourCompletion).toEqual(witness);
    });

  it("does not award the witness for unanswered, waiting-room-only or split-parent completion", () => {
    const state = createPediatricChartsQaState(context);
    const encounter = state.encounters[encounterId]!;
    recordPediatricVisitCompletion(state, encounter);
    expect(state.levelFourCompletion?.pediatricVisitWithParent).toBeFalsy();
    encounter.resolutionReason = "completed";
    encounter.lifecycle = "resolved_summary_available";
    const family = pediatricFamilyForActor(state, "encounter", encounterId)!;
    const parent = state.retailExternalActors[0]!;
    family.reservation = { roomInstanceId: "room.peds.wait", childLocation: encounter.patientLocation!,
      parentLocation: parent.location!, childSeatId: null, parentSeatId: null };
    reconcilePediatricFamilies(state, context);
    recordPediatricVisitCompletion(state, encounter);
    expect(state.levelFourCompletion?.pediatricVisitWithParent).toBeFalsy();
    family.reservation = { ...family.reservation, roomInstanceId: "room.peds.exam",
      childSeatId: "table:patient", parentSeatId: "parentChair", parentLocation: { x: 35, y: 24 } };
    recordPediatricVisitCompletion(state, encounter);
    expect(state.levelFourCompletion?.pediatricVisitWithParent).toBeFalsy();
  });
});

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { APPROVED_PEDIATRIC_SUPPORT_ROUTES, APPROVED_LEVEL4_SUPPORT_NAVIGATION } from "@gamify-surgery/balance-config";
import { advancePediatricPair, commitPediatricPairPlan, deserializeGameState, planPediatricWaiting, planPediatricExam,
  pediatricPairAtReservation, pediatricRoomAtPoint, serializeGameState, startRetailPurchase, tryStartPatientBathroomTrip,
  advanceRetailOperations, reconcilePediatricFamilies, gameReducer, pediatricSupportLocation, getRoomDefinition } from "../src";
import { getRoomWaitingAnchors } from "../src/spatial";
import { createPediatricFamilyFixture } from "../../../tests/fixtures/pediatric-families";

describe("M5b pediatric families", () => {
  it("consumes the exact M2 fine routes, rather than chair-crossing grid interpolation", () => {
    for (const [name, id] of [["pediatric-exam", "room.pediatric_examination"], ["pediatric-waiting", "room.pediatric_waiting"]] as const) {
      const approved = JSON.parse(readFileSync(new URL(`../../../apps/player/src/facility/level4/${name}.json`, import.meta.url), "utf8"));
      expect(APPROVED_PEDIATRIC_SUPPORT_ROUTES[id]).toEqual(approved.approachRoutes);
    }
  });

  it("keeps both actors together at every one of the 12 exam and 16 waiting door segments", () => {
    for (const definitionId of ["room.pediatric_examination", "room.pediatric_waiting"]) {
      const fixture = createPediatricFamilyFixture(10);
      let { state } = fixture;
      const { context, family, encounter } = fixture;
      const room = state.rooms.find(row => row.roomDefinitionId === definitionId)!;
      const definition = getRoomDefinition(definitionId, context)!;
      for (let x = room.x - 1; x <= room.x + definition.width; x++) for (let y = room.y - 1; y <= room.y + definition.height; y++) {
        if (x > room.x - 1 && x < room.x + definition.width && y > room.y - 1 && y < room.y + definition.height) continue;
        if (state.rooms.some(other => { const def = getRoomDefinition(other.roomDefinitionId, context)!;
          return x >= other.x && x < other.x + def.width && y >= other.y && y < other.y + def.height; })) continue;
        state = gameReducer(state, { type: "PLACE_ROOM", operationId: `ring.${x}.${y}`, roomId: `room.ring.${x}.${y}`,
          roomDefinitionId: "room.hallway", x, y, orientation: 0 }, context);
      }
      for (const side of ["north", "east", "south", "west"] as const) for (let offset = 0; offset < definition.width; offset++) {
        const copy = structuredClone(state);
        copy.doors = copy.doors.filter(door => door.roomId !== room.id);
        copy.doors.push({ id: `door.matrix.${side}.${offset}`, roomId: room.id, side, offset, exterior: false });
        const copiedFamily = copy.pediatricFamilies![family.id]!;
        const plan = definitionId === "room.pediatric_examination" ? planPediatricExam(copy, context, copiedFamily, copy.rooms.find(row => row.id === room.id)!)
          : planPediatricWaiting(copy, context, copiedFamily);
        expect(plan, `${definitionId} ${side} ${offset}`).toBeTruthy();
        expect(plan?.reservation?.roomInstanceId).toBe(room.id);
        for (let index = 0; index < plan!.movement.childPath.length; index++) expect(pediatricRoomAtPoint(copy, context, plan!.movement.childPath[index])?.id,
          `${definitionId} ${side} ${offset} step ${index}`).toBe(pediatricRoomAtPoint(copy, context, plan!.movement.parentPath[index])?.id);
        expect(encounter.patientAppearance.stillId).toBeTruthy();
      }
    }
  });

  it.each([9, 10, 17])("reserves age %i and an adult parent atomically and walks both lanes across doors", age => {
    const { state, context, encounter, family } = createPediatricFamilyFixture(age);
    const parent = state.retailExternalActors[0]!;
    const frozen = structuredClone([encounter.patientAppearance, parent.appearance, encounter.patientDisplayName, parent.displayName]);
    const plan = planPediatricWaiting(state, context, family)!;
    expect(plan).toBeTruthy();
    expect(family.reservation).toBeNull();
    expect(plan.reservation?.parentSeatId?.startsWith("kid")).toBe(false);
    expect(plan.reservation?.childSeatId?.startsWith("kid")).toBe(age < 10);
    const path = commitPediatricPairPlan(family, plan);
    let index = 0;
    while (index < path.length - 1) {
      const lastTick = state.facilityTick++;
      index = advancePediatricPair(state, context, family, path, index, lastTick);
      encounter.patientLocation = { ...path[index]! };
      expect(pediatricRoomAtPoint(state, context, encounter.patientLocation)?.id).toBe(pediatricRoomAtPoint(state, context, parent.location)?.id);
    }
    expect(pediatricPairAtReservation(state, family)).toBe(true);
    expect(frozen).toEqual([encounter.patientAppearance, parent.appearance, encounter.patientDisplayName, parent.displayName]);
    const examPlan = planPediatricExam(state, context, family, state.rooms.find(room => room.id === "room.peds.exam")!)!;
    expect(examPlan).toBeTruthy();
    expect(examPlan.reservation).toMatchObject({ childSeatId: "table:patient", parentSeatId: "parentChair" });
  });

  it("never schedules independent child/parent retail or bathroom movement", () => {
    const { state, context, family, encounter } = createPediatricFamilyFixture();
    expect(startRetailPurchase(state, "income.coffee", "companion", family.parentActorId, context)).toBeNull();
    expect(startRetailPurchase(state, "income.coffee", "encounter", encounter.id, context)).toBeNull();
    expect(tryStartPatientBathroomTrip(state, "encounter", encounter.id, context)).toBe(false);
    const before = structuredClone(state.retailExternalActors[0]);
    advanceRetailOperations(state, context);
    expect(state.retailExternalActors[0]).toEqual(before);
  });

  it("stalls the whole pair on access loss, retains a reload, and resumes after restoration", () => {
    const fixture = createPediatricFamilyFixture();
    let { state } = fixture;
    const { context, family, encounter } = fixture;
    const path = commitPediatricPairPlan(family, planPediatricWaiting(state, context, family)!);
    const door = state.doors.find(row => row.id === "room.peds.wait.door")!;
    state.doors = state.doors.filter(row => row.id !== door.id);
    state.facilityTick++;
    expect(advancePediatricPair(state, context, family, path, 0, 0)).toBe(0);
    expect(state.retailExternalActors[0]?.location).toEqual(encounter.patientLocation);
    state = deserializeGameState(serializeGameState(state), context);
    const restored = state.pediatricFamilies![family.id]!;
    expect(restored.movement).toEqual(family.movement);
    state.doors.push(door); state.facilityTick++;
    expect(advancePediatricPair(state, context, restored, path, 0, state.facilityTick - 1)).toBeGreaterThan(0);
  });

  it("keeps the optional M1 save fields optional and departure together", () => {
    const { state, context, family, encounter } = createPediatricFamilyFixture();
    const restored = deserializeGameState(serializeGameState(state), context);
    expect(restored.pediatricFamilies![family.id]!.movement).toBeUndefined();
    encounter.patientLocation = null;
    reconcilePediatricFamilies(state, context);
    expect(family.phase).toBe("departed");
    expect(state.retailExternalActors[0]).toMatchObject({ lifecycle: "departed", location: null });
  });

  it("uses another reachable waiting room before same-room standing overflow", () => {
    let { state, context, family } = createPediatricFamilyFixture(10);
    const room = state.rooms.find(row => row.id === "room.peds.wait")!;
    const occupy = (location: { x: number; y: number }) => state.retailExternalActors.push({
      ...structuredClone(state.retailExternalActors[0]!), id: `occupied.${state.retailExternalActors.length}`,
      pediatricFamilyId: undefined, location, path: [], lifecycle: "onsite" });
    for (const support of APPROVED_LEVEL4_SUPPORT_NAVIGATION[room.roomDefinitionId]!) occupy(pediatricSupportLocation(room, support.id)!);
    state = gameReducer(state, { type: "PLACE_ROOM", operationId: "overflow.place", roomId: "room.peds.overflow",
      roomDefinitionId: "room.pediatric_waiting", x: 23, y: 22, orientation: 0 }, context);
    state = gameReducer(state, { type: "PLACE_DOOR", operationId: "overflow.door", roomId: "room.peds.overflow",
      doorId: "overflow.door", side: "south", offset: 2 }, context);
    family = state.pediatricFamilies![family.id]!;
    const first = planPediatricWaiting(state, context, family)!;
    expect(first.reservation?.roomInstanceId).toBe("room.peds.overflow");
    expect(first.reservation?.parentSeatId?.startsWith("kid")).toBe(false);
    // With ordinary waiting/front-desk seats blocked, overflow remains in the
    // pediatric room and reserves two distinct standing points.
    const overflow = state.rooms.find(row => row.id === "room.peds.overflow")!;
    for (const support of APPROVED_LEVEL4_SUPPORT_NAVIGATION[overflow.roomDefinitionId]!) occupy(pediatricSupportLocation(overflow, support.id)!);
    const desk = state.rooms.find(row => row.roomDefinitionId === "room.front_desk")!;
    for (const point of getRoomWaitingAnchors(desk, getRoomDefinition(desk.roomDefinitionId, context)!)) occupy(point);
    const standing = planPediatricWaiting(state, context, family)!;
    expect(standing.reservation).toMatchObject({ childSeatId: null, parentSeatId: null });
    expect(standing.reservation?.childLocation).not.toEqual(standing.reservation?.parentLocation);
    expect(pediatricRoomAtPoint(state, context, standing.reservation?.childLocation)?.id)
      .toBe(pediatricRoomAtPoint(state, context, standing.reservation?.parentLocation)?.id);
  });

  it("blocks moving a reserved family room and reroutes the pair when it is sold", () => {
    let { state, context, encounter, family } = createPediatricFamilyFixture();
    const path = commitPediatricPairPlan(family, planPediatricWaiting(state, context, family)!);
    state.facilityTick += path.length;
    const index = advancePediatricPair(state, context, family, path, 0, 0);
    encounter.patientLocation = { ...path[index]! };
    const moved = gameReducer(state, { type: "MOVE_ROOM", operationId: "peds.move", roomId: "room.peds.wait", x: 29, y: 16 }, context);
    expect(moved.operationReceipts["peds.move"]?.status).toBe("rejected");
    state = gameReducer(state, { type: "SELL_ROOM", operationId: "peds.sell", roomId: "room.peds.wait" }, context);
    expect(state.operationReceipts["peds.sell"]?.status).toBe("applied");
    const savedFamily = state.pediatricFamilies![family.id]!;
    expect(savedFamily.reservation?.roomInstanceId).not.toBe("room.peds.wait");
    expect(savedFamily.movement?.parentPath).toHaveLength(savedFamily.movement!.childPath.length);
    const restored = deserializeGameState(serializeGameState(state), context);
    expect(restored.pediatricFamilies![family.id]).toEqual(savedFamily);
  });

  it("replaces both reservations after a paused door edit hides the parent's chair", () => {
    let { state, context, family, encounter } = createPediatricFamilyFixture();
    const room = state.rooms.find(row => row.id === "room.peds.wait")!;
    const plan = planPediatricWaiting(state, context, family)!;
    plan.reservation!.parentSeatId = "olderChildChair";
    plan.reservation!.parentLocation = pediatricSupportLocation(room, "olderChildChair")!;
    family.reservation = plan.reservation;
    encounter.patientLocation = { ...plan.reservation!.childLocation };
    state.retailExternalActors[0]!.location = { ...plan.reservation!.parentLocation };
    state.doors.push({ id: "peds.hidden-chair.door", roomId: room.id, side: "west", offset: 1, exterior: false });
    reconcilePediatricFamilies(state, context);
    expect(family.reservation!.parentSeatId).not.toBe("olderChildChair");
    expect(family.movement!.parentPath).toHaveLength(family.movement!.childPath.length);
    for (let i = 0; i < 80 && state.encounters[encounter.id]!.patientMovement; i++) {
      state = gameReducer({ ...state, paused: false }, { type: "ADVANCE_TICK", operationId: `peds.hidden-chair.tick.${i}` }, context);
      expect(pediatricRoomAtPoint(state, context, state.encounters[encounter.id]!.patientLocation)?.id)
        .toBe(pediatricRoomAtPoint(state, context, state.retailExternalActors[0]!.location)?.id);
    }
    expect(pediatricPairAtReservation(state, state.pediatricFamilies![family.id]!)).toBe(true);
    expect(deserializeGameState(serializeGameState(state), context).pediatricFamilies).toEqual(state.pediatricFamilies);
  });
});

import { describe, expect, it } from "vitest";
import { getServiceIncomeLine } from "@gamify-surgery/balance-config";
import { createPediatricAppointmentsQaState } from "../../../tests/fixtures/pediatric-appointments";
import { createPediatricFamilyFixture } from "../../../tests/fixtures/pediatric-families";
import { createLevelFourRoomsQaContext } from "../../../tests/fixtures/level-four-rooms";
import { advanceEmployeeMovement, advanceServiceOperations, deserializeGameState, gameReducer, getAppAppointmentHomes,
  getRoomDefinition, getRoomSalePreview, getEligibleServiceRoute, planDiagnosticOrder, pediatricFamilyForActor, pediatricPairAtReservation, pediatricRoomAtPoint, serializeGameState,
  startEncounterProcedureOperation, startServiceOperation, type GameState } from "../src";

const context = createLevelFourRoomsQaContext();
let sequence = 0;
const visits = (state: GameState) => state.serviceOperations.filter(row => row.clinicVisit?.kind === "pediatric_consult");
const learning = (state: GameState) => ({ xp: state.clinicalXp, histories: state.learningHistories, intents: state.reviewIntents,
  settlements: state.settlements, encounters: state.encounters, chart: state.openChartEncounterId, attended: state.attendedEncounterId });
function sameRoom(state: GameState) {
  for (const op of visits(state)) {
    const family = pediatricFamilyForActor(state, "service_visitor", op.id)!;
    const parent = state.retailExternalActors.find(actor => actor.id === family.parentActorId)!;
    expect(pediatricRoomAtPoint(state, context, parent.location)?.id, `Parent split from ${op.id}`).toBe(pediatricRoomAtPoint(state, context, op.location)?.id);
    if (!op.location) expect(parent.location).toBeNull();
    if (family.reservation) expect(family.reservation.parentSeatId?.startsWith("kid")).toBe(false);
  }
}
function minute(state: GameState) {
  const next = gameReducer({ ...state, paused: false }, { type: "ADVANCE_TICK", operationId: `peds.visit.tick.${sequence++}` }, context);
  sameRoom(next); return next;
}
function until(state: GameState, predicate: (value: GameState) => boolean, limit = 400) {
  for (let i = 0; i < limit && !predicate(state); i++) state = minute(state);
  expect(predicate(state), JSON.stringify(visits(state).map(row => ({ status: row.status, location: row.location, reason: row.resourceWaitReason,
    provider: row.providerReservation, path: row.path.length, index: row.pathIndex })))).toBe(true);
  return state;
}

describe("M5c pediatric APP appointments", () => {
  it("runs a family through waiting, exam and departure, freezes fees and earns a durable witness without learning", () => {
    let state = createPediatricAppointmentsQaState(context);
    const before = structuredClone(learning(state));
    state = until(state, value => visits(value).some(row => row.status === "waiting_for_resources"));
    const op = visits(state)[0]!;
    const id = op.id;
    const family = pediatricFamilyForActor(state, "service_visitor", id)!;
    expect(family.reservation?.roomInstanceId).toBe("room.peds.wait");
    expect(op.clinicVisit?.demographics.ageYears).toBeGreaterThanOrEqual(5);
    expect(op.clinicVisit?.demographics.ageYears).toBeLessThanOrEqual(17);
    expect(state.retailExternalActors).toHaveLength(1);
    const identity = JSON.parse(JSON.stringify([op.clinicVisit, op.appearance, op.displayName, state.retailExternalActors[0]?.appearance, state.retailExternalActors[0]?.displayName]));
    state = deserializeGameState(serializeGameState(state), context);
    state = until(state, value => visits(value).find(row => row.id === id)?.status === "in_service");
    const active = visits(state).find(row => row.id === id)!;
    const activeFamily = pediatricFamilyForActor(state, "service_visitor", id)!;
    expect(pediatricPairAtReservation(state, activeFamily)).toBe(true);
    expect(activeFamily.reservation).toMatchObject({ childSeatId: "table:patient", parentSeatId: "parentChair", roomInstanceId: "room.peds.exam.0" });
    expect(active.appAppointmentRevenue).toMatchObject({ fee: 80, providerEmployeeId: "app.peds.0" });
    expect(JSON.parse(JSON.stringify([active.clinicVisit, active.appearance, active.displayName, state.retailExternalActors[0]?.appearance, state.retailExternalActors[0]?.displayName]))).toEqual(identity);
    state = deserializeGameState(serializeGameState(state), context);
    state = until(state, value => visits(value).find(row => row.id === id)?.status === "completed");
    expect(state.serviceIncomeReceipts.filter(row => row.incomeLineId === "income.pediatric_consult").map(row => row.grossAmount)).toEqual([80]);
    expect(state.levelFourCompletion?.pediatricVisitWithParent).toMatchObject({ serviceOperationId: id, parentActorId: family.parentActorId });
    expect(learning(state)).toEqual(before);
    const witness = structuredClone(state.levelFourCompletion);
    state.serviceAppointmentsEnabled = false;
    state.serviceOperations = []; state.pediatricFamilies = {}; state.retailExternalActors = [];
    state = deserializeGameState(serializeGameState(state), context);
    expect(state.levelFourCompletion).toEqual(witness);
  });

  it("reuses independent per-home demand and has option-B salary/upkeep coverage", () => {
    const state = createPediatricAppointmentsQaState(context, 2);
    const line = getServiceIncomeLine("income.pediatric_consult")!;
    expect(getAppAppointmentHomes(state, context, line.id)).toHaveLength(2);
    const cost = state.employees[0]!.salaryPerExpenseInterval + getRoomDefinition("room.pediatric_examination", context)!.upkeepPerExpenseInterval +
      getRoomDefinition("room.pediatric_waiting", context)!.upkeepPerExpenseInterval;
    expect(cost).toBe(33);
    expect(line.fee * 60 / line.operation!.arrivalCadenceMinutes! - cost).toBeCloseTo(20.3333333);
    for (let i = 0; i < 600; i++) {
      state.facilityTick++; advanceEmployeeMovement(state, context); advanceServiceOperations(state, context); sameRoom(state);
    }
    // Basic 95-minute work plus paired travel is slower than 90-minute demand.
    // Five complete per home; queued demand stays bounded by the home cap.
    expect(state.serviceIncomeReceipts.filter(row => row.incomeLineId === line.id)).toHaveLength(10);
    expect(new Set(visits(state).map(row => row.clinicVisit?.requestedRoomInstanceId)).size).toBe(2);
    expect(state.nextServiceAppointmentTicks[line.id]).toBeUndefined();
  });

  it("routes a future scored fixture only to Pediatric Examination and disallows pediatric procedure starts", () => {
    let { state, encounter } = createPediatricFamilyFixture(10, context);
    state = gameReducer(state, { type: "OPEN_CHART", operationId: "peds.fixture.chart", encounterId: encounter.id }, context);
    expect(state.operationReceipts["peds.fixture.chart"]?.status).toBe("applied");
    expect(state.encounters[encounter.id]?.patientMovement?.destinationRoomInstanceId).toBe("room.peds.exam");
    expect(state.pediatricFamilies![encounter.pediatricFamilyId!]!.reservation?.parentSeatId).toBe("parentChair");
    const checkScoredPair = () => {
      const child = state.encounters[encounter.id]!;
      const parent = state.retailExternalActors.find(row => row.id === child.pediatricFamilyId!.replace("pediatric-family.", "parent."))!;
      expect(pediatricRoomAtPoint(state, context, child.patientLocation)?.id).toBe(pediatricRoomAtPoint(state, context, parent.location)?.id);
    };
    for (let i = 0; i < 80 && state.encounters[encounter.id]!.patientMovement; i++) { state = minute(state); checkScoredPair(); }
    expect(state.encounters[encounter.id]?.assignedRoomInstanceId).toBe("room.peds.exam");
    expect(pediatricPairAtReservation(state, state.pediatricFamilies![encounter.pediatricFamilyId!]!)).toBe(true);
    state = gameReducer(state, { type: "CLOSE_CHART", operationId: "peds.fixture.close", encounterId: encounter.id }, context);
    for (let i = 0; i < 80 && state.encounters[encounter.id]!.patientMovement; i++) { state = minute(state); checkScoredPair(); }
    state = deserializeGameState(serializeGameState(state), context);
    state = gameReducer(state, { type: "OPEN_CHART", operationId: "peds.fixture.reopen", encounterId: encounter.id }, context);
    for (let i = 0; i < 80 && state.encounters[encounter.id]!.patientMovement; i++) { state = minute(state); checkScoredPair(); }
    expect(pediatricPairAtReservation(state, state.pediatricFamilies![encounter.pediatricFamilyId!]!)).toBe(true);
    for (const line of ["income.mri", "income.endoscopy", "income.ambulatory_operation", "income.wound_procedure"]) {
      expect(startEncounterProcedureOperation(state, state.encounters[encounter.id]!, line, context)).toBe(false);
    }
    for (const serviceId of ["service.mrcp", "service.endoscopy", "service.endoscopy.eus-ercp-sampling"]) {
      expect(getEligibleServiceRoute(state, serviceId, null, context, encounter.id)).toBeNull();
      expect(planDiagnosticOrder(state, { serviceId, orderId: `peds.restricted.${serviceId}`, encounterId: encounter.id }, context).kind).toBe("unavailable");
    }
    // Fixture-only lifecycle states exercise the future M7 results/discharge
    // seams without adding or activating a pediatric teaching point.
    state.encounters[encounter.id]!.lifecycle = "active_pending_result";
    state = gameReducer(state, { type: "CLOSE_CHART", operationId: "peds.fixture.results", encounterId: encounter.id }, context);
    for (let i = 0; i < 20; i++) { state = minute(state); checkScoredPair(); }
    state = deserializeGameState(serializeGameState(state), context);
    checkScoredPair();
    expect(state.pediatricFamilies![encounter.pediatricFamilyId!]!.phase).toBe("results_wait");
    state.encounters[encounter.id]!.lifecycle = "resolved_summary_available";
    state.encounters[encounter.id]!.terminalFeedback = {
      kind: "completion", outcome: null, consequence: null, correction: null, acknowledged: true,
    };
    state = gameReducer(state, { type: "CLOSE_CHART", operationId: "peds.fixture.discharge", encounterId: encounter.id }, context);
    for (let i = 0; i < 80 && state.encounters[encounter.id]!.patientLocation; i++) { state = minute(state); checkScoredPair(); }
    expect(state.encounters[encounter.id]!.patientLocation).toBeNull();
    expect(state.pediatricFamilies![encounter.pediatricFamilyId!]!.phase).toBe("departed");
  });

  it("waits through real APP training and freezes the actual returning provider's fee", () => {
    let state = createPediatricAppointmentsQaState(context);
    state = until(state, value => visits(value).some(row => row.status === "in_service"));
    state = gameReducer(state, { type: "TRAIN_EMPLOYEE", operationId: "peds.train", employeeId: "app.peds.0" }, context);
    expect(state.operationReceipts["peds.train"]?.status).toBe("applied");
    expect(state.employees[0]?.training?.stage).toBe("queued");
    state = until(state, value => value.employees[0]?.training?.stage === "training");
    state.nextServiceAppointmentTicks["income.pediatric_consult:room.peds.exam.0"] = state.facilityTick;
    state = until(state, value => visits(value).some(row => row.status === "waiting_for_resources"));
    const id = visits(state).find(row => row.status === "waiting_for_resources")!.id;
    state = deserializeGameState(serializeGameState(state), context);
    state = until(state, value => visits(value).find(row => row.id === id)?.completedAtFacilityTick !== null);
    const operation = visits(state).find(row => row.id === id)!;
    expect(operation.appAppointmentRevenue).toMatchObject({ fee: 88, trainingPercent: 10, providerEmployeeId: "app.peds.0" });
    const frozen = structuredClone(operation.appAppointmentRevenue);
    state.employees[0]!.trainingLevel = 5;
    state = deserializeGameState(serializeGameState(state), context);
    expect(visits(state).find(row => row.id === id)?.appAppointmentRevenue).toEqual(frozen);
  });

  it("keeps a stalled family together after door loss and reload, then resumes with no unpaid credit", () => {
    let state = createPediatricAppointmentsQaState(context);
    state = until(state, value => visits(value).some(row => row.status === "walking_to_service"));
    const id = visits(state).find(row => row.status === "walking_to_service")!.id;
    state.serviceAppointmentsEnabled = false;
    const door = state.doors.find(row => row.id === "room.peds.exam.0.door")!;
    state.doors = state.doors.filter(row => row.id !== door.id);
    const op = visits(state).find(row => row.id === id)!;
    const family = pediatricFamilyForActor(state, "service_visitor", id)!;
    const frozenIdentity = structuredClone([op.appearance, state.retailExternalActors.find(row => row.id === family.parentActorId)!.appearance]);
    for (let i = 0; i < 90; i++) state = minute(state);
    expect(visits(state).find(row => row.id === id)?.status).toBe("waiting_for_resources");
    expect(state.serviceIncomeReceipts).toHaveLength(0);
    expect(state.levelFourCompletion?.pediatricVisitWithParent).toBeFalsy();
    state = deserializeGameState(serializeGameState(state), context); sameRoom(state);
    state.doors.push(door);
    state = until(state, value => visits(value).find(row => row.id === id)?.status === "completed");
    expect(state.serviceIncomeReceipts).toHaveLength(1);
    expect([visits(state).find(row => row.id === id)!.appearance, state.retailExternalActors.find(row => row.id === family.parentActorId)!.appearance]).toEqual(frozenIdentity);
  });

  it("evacuates a sold exam together and preserves remaining work and the frozen fee in a second home", () => {
    let state = createPediatricAppointmentsQaState(context, 2);
    state.serviceAppointmentsEnabled = false;
    const id = startServiceOperation(state, "income.pediatric_consult", "visitor", context)!;
    state = until(state, value => visits(value).find(row => row.id === id)?.status === "in_service");
    const active = visits(state).find(row => row.id === id)!;
    const roomId = active.reservedRoomInstanceIds[0]!;
    const frozenFee = structuredClone(active.appAppointmentRevenue);
    const sale = getRoomSalePreview(state, roomId, context)!;
    state = gameReducer(state, { type: "SELL_ROOM", operationId: "peds.sale", roomId, saleConfirmationToken: sale.confirmationToken }, context);
    expect(state.operationReceipts["peds.sale"]?.status).toBe("applied");
    sameRoom(state);
    expect(visits(state).find(row => row.id === id)?.saleTransfer?.remainingPhaseMinutes).toBe(95);
    state = deserializeGameState(serializeGameState(state), context);
    state = until(state, value => visits(value).find(row => row.id === id)?.status === "completed");
    expect(visits(state).find(row => row.id === id)?.appAppointmentRevenue).toEqual(frozenFee);
    expect(state.serviceIncomeReceipts).toHaveLength(1);
    expect(state.levelFourCompletion?.pediatricVisitWithParent?.serviceOperationId).toBe(id);
  });

  it("departs together without payment or completion when the last pediatric exam is sold", () => {
    let state = createPediatricAppointmentsQaState(context);
    state.serviceAppointmentsEnabled = false;
    const id = startServiceOperation(state, "income.pediatric_consult", "visitor", context)!;
    state = until(state, value => visits(value).find(row => row.id === id)?.status === "in_service");
    const roomId = visits(state).find(row => row.id === id)!.reservedRoomInstanceIds[0]!;
    const sale = getRoomSalePreview(state, roomId, context)!;
    state = gameReducer(state, { type: "SELL_ROOM", operationId: "peds.last.sale", roomId, saleConfirmationToken: sale.confirmationToken }, context);
    state = deserializeGameState(serializeGameState(state), context);
    state = until(state, value => visits(value).find(row => row.id === id)?.status === "cancelled");
    expect(state.serviceIncomeReceipts).toHaveLength(0);
    expect(state.levelFourCompletion?.pediatricVisitWithParent).toBeFalsy();
    expect(state.retailExternalActors.find(row => row.linkedServiceOperationId === id)?.location).toBeNull();
  });
});

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { SYNTHETIC_CLINICAL_RELEASE } from "@gamify-surgery/clinical-content";
import { PEDIATRIC_CHARACTER_STILLS, pediatricStillEligibleEntries, patientStillEligibleEntries,
  createPatientPixelAppearance, createPatientDisplayName, completePatientDemographics,
  selectPatientStillId, pediatricCaseHasCompatibleIdentity } from "../src";

describe("M5a pediatric identity", () => {
  it("reviews all twelve source briefs without inferring sex from their pixels", () => {
    const source = JSON.parse(readFileSync(new URL("../../../tools/character-mapping/level3-roster-complete-v2/roster.json", import.meta.url), "utf8"));
    expect(PEDIATRIC_CHARACTER_STILLS).toHaveLength(12);
    for (const entry of PEDIATRIC_CHARACTER_STILLS) {
      const row = source.identities.find((identity: { stableId: string }) => identity.stableId === entry.stillId);
      expect(row.visualAge).toBe(entry.intendedVisualAge);
      expect(row.brief.startsWith(entry.compatibleSexLabel === "Female" ? "girl" : "boy")).toBe(true);
      expect([entry.minimumAge, entry.maximumAge]).toEqual(row.targetKey === "younger-child" ? [5, 8] : row.targetKey === "older-child" ? [9, 12] : [13, 17]);
    }
  });

  it("covers both sexes at every launch age, never using an adult identity", () => {
    for (let ageYears = 5; ageYears <= 17; ageYears++) for (const sexLabel of ["Female", "Male"] as const) {
      const eligible = pediatricStillEligibleEntries(sexLabel, ageYears);
      expect(eligible.length).toBeGreaterThan(0);
      for (let index = 0; index < 20; index++) {
        const appearance = createPatientPixelAppearance("child.identity", `child.${ageYears}.${sexLabel}.${index}`, { ageYears, sexLabel });
        expect(eligible.some(entry => entry.stillId === appearance.stillId)).toBe(true);
        expect(appearance.patientIdentityId).toBeUndefined();
        expect(selectPatientStillId("reload", "child", { ageYears, sexLabel }, appearance.stillId)).toBe(appearance.stillId);
        const name = createPatientDisplayName("child.identity", "child.name", sexLabel);
        expect(createPatientDisplayName("child.identity", "child.name", sexLabel)).toBe(name);
      }
      expect(patientStillEligibleEntries(sexLabel, ageYears)).toEqual([]);
    }
  });

  it("rejects missing/out-of-range pediatric demographics and arbitrary/adult saved stills", () => {
    for (const ageYears of [0, 4, 18, 30]) expect(pediatricStillEligibleEntries("Male", ageYears)).toEqual([]);
    expect(pediatricStillEligibleEntries("Not specified", 8)).toEqual([]);
    expect(selectPatientStillId("seed", "child", { ageYears: 8, sexLabel: "Male" }, "patient.adult.001")).toMatch(/^level3-roster-v2\./);
    expect(selectPatientStillId("seed", "child", { ageYears: 4, sexLabel: "Male" }, "future.unknown")).toBeUndefined();
    expect(() => completePatientDemographics({ caseId: "fixture", campaignSeed: "s", encounterId: "c", pediatric: true })).toThrow("explicit age");
    const demographics = { ageYears: 9, sexLabel: "Female" as const };
    expect(completePatientDemographics({ caseId: "fixture", campaignSeed: "s", encounterId: "c", pediatric: true, demographics })).toEqual(demographics);
    const fixture = structuredClone(SYNTHETIC_CLINICAL_RELEASE.cases[0]!);
    fixture.prototypeDemographics = demographics;
    expect(pediatricCaseHasCompatibleIdentity(fixture)).toBe(false);
    fixture.pediatricProfile = { version: "pediatric-patient-profile.v1", requiresParent: true, clinicalScope: "outpatient" };
    expect(pediatricCaseHasCompatibleIdentity(fixture)).toBe(true);
    fixture.prototypeDemographics = { ageYears: 4, sexLabel: "Female" };
    expect(pediatricCaseHasCompatibleIdentity(fixture)).toBe(false);
  });
});
